"use strict";

// N4 grammar: the 50 Tanos N4 points (`ref` = their Tanos names, tools/ref/n4.json) plus confirmed extras
// (`offList`, ≥2 independent sources in `sources`) and form points (`offList`: adjective/noun て-form, なくて,
// noun-modifying clauses, ていた, potential, imperative, な prohibitive) placed before the patterns built on them.
// The volitional, ば, passive, causative and causative-passive forms are Tanos points and carry `ref`.
// Meanings and notes are our own words; the linked pages only confirm level and meaning.
// Method + sources: tools/n4-grammar-notes.md. Examples live in sentences.js.
CATALOG.add([
  // ── Blocks 1-7: plain form, linking, wanting, appearance, ability, giving, aspect ──
  { id: 'g:te-adj-noun', kind: 'grammar', level: 'N4', conjForm: 'くて-form', hl: ['(くて)', '(?<=(?:しずか|静か|きれい|元気|げんき|ひま|すき|好き|上手|下手|有名|大切|親切|べんり|病気|学生|雨|休み|かんたん))(で)(?!す|し|は|も)'], pattern: '〜くて/〜で (adjective and noun て-form)', meaning: 'is ~ and …; because it is ~ (linking adjectives and nouns)', formation: 'い-adj: drop い, add くて ([安|やす]い → [安|やす]くて; いい → よくて); な-adj / noun + で (しずかで, [病気|びょうき]で)', notes: 'This is the て-form for adjectives and nouns, so a description can go on: [安|やす]くて、おいしい "cheap and tasty". The first part can also be the reason: [病気|びょうき]で[休|やす]みました "I was off because I was sick". Join two good points or two bad points this way; for a contrast use けど or が instead. Verbs already have their own て-form (g:te-form).', examples: ['s:own:n4-te-adj-noun-heya', 's:tatoeba:10901873', 's:own:n4-te-adj-noun-ramen', 's:tatoeba:190695', 's:tatoeba:10901517', 's:own:n4-te-adj-noun-hon'], offList: 'form point, not a Tanos pattern; Bunpro N4 "Verb[て]・Noun[で] + B", Genki I ch.7', sources: ['https://bunpro.jp/grammar_points/verb-%E3%81%A6-noun-%E3%81%A7-b', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/te-form-joining-sentences-genki-i-chapter-7/'], verified: true },
  { id: 'g:nakute', kind: 'grammar', level: 'N4', conjForm: 'なくて-form', hl: ['(なくて)'], pattern: '〜なくて/〜じゃなくて', meaning: 'not ~, and …; because (something) does not ~; not X but Y', formation: 'V-ない → なくて (わからない → わからなくて); い-adj くない → くなくて; N / な-adj + じゃなくて (ではなくて)', notes: 'The て-form of ない. It links a negative to what follows, often as the reason: お[金|かね]が[足|た]りなくて[買|か]えない. With nouns, X じゃなくて Y means "not X but Y". Do not mix it up with 〜ないで (g:nai-de), "without doing / instead of doing", which links two actions by the same person.', examples: ['s:own:n4-nakute-imi', 's:tatoeba:11527067', 's:tatoeba:10140581', 's:tatoeba:172932'], offList: 'form point, not a Tanos pattern; Bunpro lists なくて at N4 (with ないで as its contrast pair)', sources: ['https://bunpro.jp/grammar_points/%E3%81%AA%E3%81%8F%E3%81%A6', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/te-form-joining-sentences-genki-i-chapter-7/'], verified: true },
  { id: 'g:noun-modifier', kind: 'grammar', level: 'N4', hl: ['([ただるい])(?=(?:人|ひと|本|ほん|車|くるま|もの|店|みせ))'], pattern: 'V-た N / V-る N (noun-modifying clause)', meaning: 'the N that …; the person who … (a sentence describing a noun)', formation: 'Plain form (dictionary, ない, た, ている; い-adj; な-adj + な; N + の) + noun: きのう[買|か]った[本|ほん], めがねをかけている[人|ひと]', notes: 'Japanese puts the describing sentence before the noun, with no word for "who" or "that": きのう[買|か]った[本|ほん] "the book (I) bought yesterday". The verb is in plain form, even in polite speech. The subject inside the clause takes が or の, never は: トムの[買|か]った[車|くるま].', examples: ['s:own:n4-noun-modifier-hon', 's:tatoeba:11831566', 's:tatoeba:1107908', 's:own:n4-noun-modifier-megane', 's:tatoeba:11720950'], offList: 'form point, not a Tanos pattern; Genki I ch.9 + Genki II ch.15 teach noun-modifying clauses', sources: ['https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/qualifying-nouns-with-verbs-and-adjectives-genki-i-chapter-9/', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/using-sentences-to-qualify-nouns-genki-ii-chapter-15/'], verified: true },
  { id: 'g:te-ita', kind: 'grammar', level: 'N4', hl: ['([てで](?:いた|いました|た)(?=[。、よね]|$))'], pattern: '〜ていた/〜ていました', meaning: 'was ~ing; was in a state (after a change) at that time', formation: 'V-て + いた (polite いました); casual speech drops the い: してた', notes: 'The past of 〜ている (g:te-iru). With action verbs it says what was going on at a past moment: [本|ほん]を[読|よ]んでいました "I was reading a book". With verbs of change it gives the state at that time: ドアは[開|あ]いていた "the door was open". Plain 〜た only reports that something happened.', examples: ['s:tatoeba:152797', 's:tatoeba:225305', 's:tatoeba:12515162', 's:own:n4-te-ita-denwa'], offList: 'form point, not a Tanos pattern; Bunpro lists ていた at N4; Genki I ch.7 teaches ている with its past', sources: ['https://bunpro.jp/grammar_points/%E3%81%A6%E3%81%84%E3%81%9F', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/teiru-genki-i-chapter-7/'], verified: true },
  { id: 'g:to-omou', kind: 'grammar', level: 'N4', hl: ['(と)(?=(?:思|おも))'], pattern: '〜と思う', meaning: 'I think (that) ~', formation: 'Plain form + と[思|おも]う: [雨|あめ]がふると[思|おも]います; N / な-adj + だ + と[思|おも]う: [先生|せんせい]だと[思|おも]います', notes: 'と marks what is thought, in plain form even when the sentence ends in [思|おも]います. Nouns and な-adjectives need だ before と. For someone else\'s opinion use [思|おも]っている: [兄|あに]はそう[思|おも]っている. 〜と[言|い]う "say that" works the same way.', examples: ['s:tatoeba:10899511', 's:tatoeba:171704', 's:tatoeba:2121372', 's:tatoeba:161836'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list と思う at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%A8%E3%81%8A%E3%82%82%E3%81%86', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%a8%e3%81%8a%e3%82%82%e3%81%86-to-omou/'], verified: true },
  { id: 'g:tte', kind: 'grammar', level: 'N4', pattern: '〜って', meaning: 'casual quote ("says that / said …"); casual topic ("as for ~, …")', formation: 'Plain form + って (= と in quotes): [来|く]るって[言|い]ってた; N + って (= は, asking about it): [名前|なまえ]って[何|なん]？', notes: 'The casual spoken stand-in for the quoting と ([来|く]るって[言|い]ってた) and for は when you ask what something is or how it is ([日本|にほん]ってどう[思|おも]う？). Ending a sentence with 〜んだって passes on something you heard. Keep it out of polite writing.', examples: ['s:tatoeba:10671730', 's:own:n4-tte-otoutosan', 's:tatoeba:9725630'], offList: 'not on Tanos N4; Bunpro (N5) and Genki II ch.17 teach quotative って', sources: ['https://bunpro.jp/grammar_points/%E3%81%A3%E3%81%A6', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/tte%c2%81-%c2%81aa-genki-ii-chapter-17/'], verified: true },
  { id: 'g:to-iu', kind: 'grammar', level: 'N4', pattern: '〜という〜', meaning: 'a N called X; the N that says …', formation: 'Name / word + という + N: ジョンという[名前|なまえ]; plain clause + という + N: [会|あ]いたいという[人|ひと]', notes: 'Use it to name something the listener may not know: [何|なん]という[花|はな]ですか "what is this flower called?". After a sentence it gives the content of a noun such as [人|ひと], [話|はなし] or ニュース. It is usually written in kana. Saying your own name is と[言|い]います (N5 style), a different use.', examples: ['s:tatoeba:3481397', 's:tatoeba:211000', 's:tatoeba:233719'], ref: ['～という～'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/name-toiu-item-genki-ii-chapter-20/'], verified: true },
  { id: 'g:koto', kind: 'grammar', level: 'N4', pattern: '〜こと', meaning: 'doing ~ (turns a verb phrase into a noun)', formation: 'V (plain form) + こと: [読|よ]むこと, [聞|き]くこと', notes: 'こと turns a verb phrase into a noun, so it can be the topic or the end of a sentence: [本|ほん]を[読|よ]むことは[大切|たいせつ]です, しゅみは[音楽|おんがく]を[聞|き]くことです. の does the same job in 〜のが[好|す]き (N5); こと is needed after です ("my hobby is ~ing") and in 〜ことができる (g:koto-ga-dekiru).', examples: ['s:own:n4-koto-shumi', 's:tatoeba:81616', 's:tatoeba:184779'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list nominaliser こと at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%93%E3%81%A8', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%93%e3%81%a8-koto-1/'], verified: true },
  { id: 'g:to-iu-koto', kind: 'grammar', level: 'N4', pattern: '〜ということ', meaning: 'the fact that ~; it means that ~', formation: 'Plain form + ということ (N / な-adj + だ + ということ)', notes: 'Wraps a whole sentence as one thing (the fact, the news, the point) so you can know it, hear it or explain it: [先生|せんせい]だということを[知|し]っています. At the end, 〜ということです states what something comes down to: [問題|もんだい]はお[金|かね]がないということです.', examples: ['s:tatoeba:161813', 's:tatoeba:79848', 's:own:n4-to-iu-koto-test'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list ということ at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%A8%E3%81%84%E3%81%86%E3%81%93%E3%81%A8', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%a8%e3%81%84%e3%81%86%e3%81%93%e3%81%a8-to-iu-koto/'], verified: true },
  { id: 'g:shi', kind: 'grammar', level: 'N4', hl: ['(?:い|だ|る|た|ない)(し)(?=、)'], pattern: '〜し', meaning: '~, and what is more ~ (adding up reasons or points)', formation: 'Plain form + し: [安|やす]いし, [行|い]くし, [行|い]かないし; N / な-adj + だし: しずかだし', notes: 'し lists points that pile up toward one conclusion, often a reason: [安|やす]いし、おいしいし、よく[来|き]ます. It suggests there may be more reasons left unsaid, so one し can be enough. て-form linking ([安|やす]くて) only describes; し argues. Polite speech can use です / ます before し.', examples: ['s:own:n4-shi-mise', 's:own:n4-shi-heya', 's:tatoeba:224297', 's:tatoeba:10969586', 's:tatoeba:1866547'], ref: ['～し'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/shi-genki-ii-chapter-13/'], verified: true },
  { id: 'g:nado', kind: 'grammar', level: 'N4', pattern: '〜など', meaning: '~ and so on, things like ~', formation: 'N (や N) + など (+ particle): [肉|にく]や[魚|さかな]などを[買|か]った', notes: 'など says the list is only a sample. It often closes a や list (N5 g:ya): [本|ほん]やノートなど. After one noun it softens a suggestion: お[茶|ちゃ]などいかがですか "some tea, perhaps?". It is a little more written than とか (g:toka-toka).', examples: ['s:own:n4-nado-suupaa', 's:own:n4-nado-tsukue', 's:tatoeba:1987791'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list など at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%AA%E3%81%A9', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%aa%e3%81%a9-nado/'], verified: true },
  { id: 'g:toka-toka', kind: 'grammar', level: 'N4', pattern: '〜とか〜とか', meaning: 'things like ~ and ~ (casual list of examples)', formation: 'N / plain form + とか + N / plain form + とか: そうじとかせんたくとか', notes: 'A casual way to give examples, like や〜など but more spoken. Unlike や, it can list verbs too: [本|ほん]を[読|よ]むとか、[音楽|おんがく]を[聞|き]くとか. The last とか is often dropped.', examples: ['s:own:n4-toka-yasumi', 's:own:n4-toka-ryouri', 's:own:n4-toka-pen'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list とか〜とか at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%A8%E3%81%8B-%E3%81%A8%E3%81%8B', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%a8%e3%81%8b%ef%bd%9e%e3%81%a8%e3%81%8b-tokatoka/'], verified: true },
  { id: 'g:dake-de', kind: 'grammar', level: 'N4', pattern: '〜だけで', meaning: 'just by ~ / with only ~', formation: 'V (plain) + だけで: [聞|き]くだけで; N + だけで: [二人|ふたり]だけで', notes: 'Builds on だけ "only" (N5 g:dake). With で it says that this one small thing is enough for the result: [聞|き]いているだけで[楽|たの]しくなる "just listening makes me happy". 〜だけでいい means "all you need to do is ~". After a noun it means "with only ~": [二人|ふたり]だけで[話|はな]す.', examples: ['s:own:n4-dake-de-uta', 's:tatoeba:10808978', 's:tatoeba:9042473', 's:tatoeba:1683201'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list だけで at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%A0%E3%81%91%E3%81%A7', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%a0%e3%81%91%e3%81%a7-dake-de/'], verified: true },
  { id: 'g:sore-ni', kind: 'grammar', level: 'N4', pattern: 'それに', meaning: 'besides, on top of that', formation: 'Sentence。それに、sentence', notes: 'Starts a sentence that adds one more point in the same direction: [安|やす]いです。それに、おいしいです. It often goes with し in the first sentence. To add a point against what came before, use それでも or でも instead.', examples: ['s:own:n4-sore-ni-mise', 's:own:n4-sore-ni-ame', 's:tatoeba:1866547'], offList: 'not on Tanos N4; Bunpro lists それに at N4; JLPT Sensei name (borderline vocabulary, kept for 文章の文法 connectors)', sources: ['jlptsensei', 'https://bunpro.jp/grammar_points/%E3%81%9D%E3%82%8C%E3%81%AB'], verified: true },
  { id: 'g:sore-demo', kind: 'grammar', level: 'N4', pattern: 'それでも', meaning: 'even so, and yet', formation: 'Sentence。それでも、sentence', notes: 'The second sentence happens in spite of the first: [雨|あめ]でした。それでも、[出|で]かけました. It is stronger than でも "but": you expected the first fact to stop the second. Compare それに, which adds a point in the same direction.', examples: ['s:own:n4-sore-demo-ame', 's:own:n4-sore-demo-test', 's:tatoeba:11619795', 's:own:n4-sore-demo-shukudai'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list それでも at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%9D%E3%82%8C%E3%81%A7%E3%82%82', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%9d%e3%82%8c%e3%81%a7%e3%82%82-sore-demo/'], verified: true },
  { id: 'g:demo', kind: 'grammar', level: 'N4', pattern: '〜でも', meaning: 'any ~ at all (with question words); ~ or something (a soft suggestion)', formation: 'Question word + でも: [何|なん]でも, だれでも, いつでも, どこでも; N + でも: お[茶|ちゃ]でも', notes: 'After a question word, でも makes "any ~ at all": [何|なん]でも[食|た]べます "I eat anything". After a plain noun it offers it as one idea among others: お[茶|ちゃ]でも[飲|の]みませんか "how about some tea or something?". Do not confuse it with でも "but" at the start of a sentence, or with 〜ても "even if" (g:te-mo).', examples: ['s:tatoeba:8534126', 's:own:n4-demo-koohii', 's:tatoeba:2992032', 's:own:n4-demo-dare'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list でも at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%A7%E3%82%82', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%a7%e3%82%82-demo/'], verified: true },
  { id: 'g:ga-hoshii', kind: 'grammar', level: 'N4', hl: ['(がほし|が欲し)'], pattern: '〜がほしい', meaning: 'want (a thing)', formation: 'N + が + ほしい (conjugates like an い-adjective: ほしくない, ほしかった)', notes: 'ほしい is for things; for actions use 〜たい (N5 g:tai): [車|くるま]がほしい but [車|くるま]を[買|か]いたい. It describes the speaker\'s own wish (or asks the listener\'s); for a third person use ほしがっている (g:tagaru). Asking a superior ほしいですか sounds pushy; offer instead (いかがですか).', examples: ['s:own:n4-ga-hoshii-kaban', 's:tatoeba:151216', 's:tatoeba:161578', 's:tatoeba:187929'], ref: ['～がほしい'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/hoshi-genki-ii-chapter-14/'], verified: true },
  { id: 'g:te-hoshii', kind: 'grammar', level: 'N4', hl: ['([てで]ほし)'], pattern: '〜てほしい', meaning: 'want someone to do ~', formation: 'Person + に + V-て + ほしい: [友|とも]だちに[来|き]てほしい; negative V-ないで + ほしい (or V-て + ほしくない)', notes: 'The person you want to act takes に: [母|はは]に[聞|き]いてほしい. Compare がほしい (g:ga-hoshii), wanting a thing, and 〜たい, wanting to do it yourself. Said straight to someone it is a fairly direct wish; a polite request uses 〜てください or 〜ていただけませんか (g:te-itadakemasen-ka).', examples: ['s:own:n4-te-hoshii-matsu', 's:tatoeba:157464', 's:tatoeba:1152237', 's:tatoeba:164300'], ref: ['～のようてほしい'], sources: ['tanos', 'https://bunpro.jp/grammar_points/%E3%81%A6%E3%81%BB%E3%81%97%E3%81%84', 'https://japanesetest4you.com/flashcard/learn-japanese-grammar-41/', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/tehoshi-genki-ii-chapter-21/'], verified: true },
  { id: 'g:tagaru', kind: 'grammar', level: 'N4', hl: ['(たが)(?=[るりっらろ])'], pattern: '〜たがる/〜たがっている', meaning: '(someone else) wants to ~ (as you can see)', formation: 'V-ます stem + たがる (a う-verb): [行|い]きたがる, [行|い]きたがっている; also ほしがる from ほしい', notes: 'You cannot see inside other people, so their wishes are reported as signs: [弟|おとうと]は[行|い]きたがっている "my brother (acts like he) wants to go". Use 〜たい / ほしい for yourself; use 〜たがる for a third person, usually as 〜たがっている for now. 〜がる also turns some feeling adjectives into "shows signs of": [寒|さむ]がる.', examples: ['s:own:n4-tagaru-otouto', 's:tatoeba:10796446', 's:tatoeba:2662459', 's:tatoeba:9752002'], ref: ['～たがる'], sources: ['tanos', 'https://bunpro.jp/grammar_points/%E3%81%9F%E3%81%8C%E3%82%8B', 'https://japanesetest4you.com/flashcard/learn-japanese-grammar-35/'], verified: true },
  { id: 'g:ga-suru', kind: 'grammar', level: 'N4', hl: ['(が(?:する|します|しました|した))'], pattern: '〜がする/〜がします/〜がした', meaning: 'there is a (sound / smell / taste); I have a feeling that ~', formation: '[音|おと] / [声|こえ] / におい / [味|あじ] + が + する; plain form + [気|き]がする', notes: 'する here means "be sensed", not "do": [音|おと]がする "I hear a sound", いいにおいがする "it smells good", [魚|さかな]の[味|あじ]がする "it tastes of fish". 〜[気|き]がする is a soft "I have a feeling that ~". The sense is noticed, not made: it is not [音|おと]を[聞|き]く.', examples: ['s:own:n4-ga-suru-nioi', 's:tatoeba:11483540', 's:tatoeba:223647', 's:tatoeba:2478353', 's:tatoeba:8505146'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list がする at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%8C%E3%81%99%E3%82%8B', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%8c%e3%81%99%e3%82%8b-ga-suru/'], verified: true },
  { id: 'g:sa', kind: 'grammar', level: 'N4', hl: ['(?:[高長重広大強寒暑早明]|大き|やさし|おもしろ)(さ)'], pattern: '〜さ', meaning: '-ness: turns an adjective into a noun of degree (height, length, weight)', formation: 'い-adj: drop い, add さ ([高|たか]い → [高|たか]さ, [大|おお]きい → [大|おお]きさ; いい → よさ); な-adj stem + さ (しずかさ)', notes: 'さ names how much of a quality something has, so you can measure or compare it: [高|たか]さ "height", [重|おも]さ "weight", [長|なが]さ "length". It often comes with どれくらい or [同|おな]じ: [同|おな]じ[長|なが]さです. Some adjectives also have a み noun with a feeling sense ([楽|たの]しみ, [痛|いた]み), but さ is the general one.', examples: ['s:own:n4-sa-yama', 's:tatoeba:218746', 's:tatoeba:210451', 's:own:n4-sa-kaban'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list さ at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%95', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%95-sa/'], verified: true },
  { id: 'g:sou-da-looks', kind: 'grammar', level: 'N4', hl: ['(?<=[きぎしじちにひびみりえけげせてねべめれさ])(そう)(?=[だでなに])'], pattern: '〜そうだ/〜そうです/〜そうな/〜そうに (looks like)', meaning: 'looks ~; looks like it is about to ~ (judging by appearance)', formation: 'V-ます stem + そう ([雨|あめ]がふりそう); い-adj minus い + そう (おいしそう; いい → よさそう, ない → なさそう); な-adj + そう (げんきそう). Before a noun そうな, before a verb そうに', notes: 'You say what you see: おいしそうな[料理|りょうり] "food that looks delicious", [雨|あめ]になりそうだ "it looks like rain". With verbs it means something seems about to happen. Do not use it for things that are obvious at a glance (きれいな[花|はな] is just きれい). The hearsay そうだ (g:sou-da-hearsay) attaches to the plain form instead: ふるそうだ "I hear it will rain".', examples: ['s:own:n4-sou-da-looks-keeki', 's:tatoeba:227830', 's:tatoeba:216464', 's:tatoeba:80451', 's:tatoeba:10809041'], ref: ['～そうです'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/so-desu-looks-like-genki-ii-chapter-13/'], verified: true },
  { id: 'g:mitai', kind: 'grammar', level: 'N4', hl: ['(みたい)(?=[だでなに。ねよ、]|$)'], pattern: '〜みたい(だ)', meaning: 'seems ~; like ~ (casual)', formation: 'Plain form / N + みたい (no だ before it: [病気|びょうき]みたい); before a noun みたいな, before a verb みたいに', notes: 'A casual "it seems / it looks like", judging from what you see or hear: [病気|びょうき]みたい "(it) seems sick", [夏|なつ]みたいだ "it is like summer". It conjugates like a な-adjective: [子|こ]どもみたいな[人|ひと], [先生|せんせい]みたいに[話|はな]す. Its written partner is ようだ (g:you-da). Don\'t confuse it with 〜てみたい "want to try" or 〜たい after a ます-stem ([見|み]たい).', examples: ['s:tatoeba:184879', 's:tatoeba:11052242', 's:tatoeba:12054409', 's:own:n4-mitai-ani'], ref: ['～みたい'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/mitaidesu-genki-ii-chapter-17/'], verified: true },
  { id: 'g:you-da', kind: 'grammar', level: 'N4', hl: ['(よう)(?=だ|です|でした)'], pattern: '〜ようだ/〜ようです', meaning: 'it seems that ~; it appears ~ (a judgment from what you notice)', formation: 'Plain form + ようだ; N + の + ようだ ([雨|あめ]のようだ); な-adj + な + ようだ', notes: 'A careful, slightly formal "it seems": you are drawing a conclusion from what you notice. みたい (g:mitai) says the same in conversation. そうだ (looks, g:sou-da-looks) is about appearance right in front of you; ようだ weighs all the signs. らしい, "apparently", comes at N3.', examples: ['s:tatoeba:171129', 's:tatoeba:171535', 's:tatoeba:230329', 's:tatoeba:3367120'], offList: 'not on Tanos N4 (Tanos ～よう is the volitional); Bunpro + japanesetest4you list ようだ at N4', sources: ['https://bunpro.jp/grammar_points/%E3%82%88%E3%81%86%E3%81%A0', 'https://japanesetest4you.com/flashcard/learn-jlpt-n3-grammar-%e3%82%88%e3%81%86%e3%81%a0-you-da/'], verified: true },
  { id: 'g:no-you-na', kind: 'grammar', level: 'N4', hl: ['(のよう[なに])'], pattern: '〜のような/〜のように', meaning: 'like ~ (a comparison or an example)', formation: 'N + の + ような + N ([父|ちち]のような[医者|いしゃ]); N + の + ように + verb / adjective ([風|かぜ]のように[走|はし]る)', notes: 'Compares something to N: レモンのような[味|あじ] "a taste like lemon", [風|かぜ]のように[走|はし]る "run like the wind". ような comes before a noun, ように before a verb or adjective. It can also give an example: [先生|せんせい]のような[人|ひと] "someone like a teacher". みたいな / みたいに (g:mitai) is the casual version.', examples: ['s:own:n4-no-you-na-isha', 's:tatoeba:12296469', 's:tatoeba:4930', 's:own:n4-no-you-ni-haha', 's:tatoeba:161400'], ref: ['～のような', '～のように'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/noyona-noyoni-genki-ii-chapter-22/'], verified: true },
  { id: 'g:sou-da-hearsay', kind: 'grammar', level: 'N4', hl: ['(?<=[るたいだ])(そう)(?=だ|です)'], pattern: '〜そうだ/〜そうです (I hear)', meaning: 'I hear that ~; they say ~', formation: 'Plain form + そうだ: ふるそうだ, [買|か]ったそうだ, [高|たか]いそうだ; N / な-adj + だ + そうだ: [雨|あめ]だそうです', notes: 'Passes on information you got from someone else; the source often comes first with によると or と[聞|き]いた. The verb before it stays in plain form, and そうだ itself does not change to past. Compare the "looks" そう (g:sou-da-looks), which attaches to a stem: ふりそうだ "it looks like rain".', examples: ['s:own:n4-sou-da-hearsay-ame', 's:tatoeba:1594278', 's:tatoeba:189072', 's:own:n4-sou-da-hearsay-tomodachi'], ref: ['そうです'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/so-desu-i-hear-genki-ii-chapter-17/'], verified: true },
  { id: 'g:kamo-shirenai', kind: 'grammar', level: 'N4', hl: ['(かもしれ(?:ない|ません))'], pattern: '〜かもしれない/〜かもしれません', meaning: 'might ~, maybe ~', formation: 'Plain form + かもしれない; N / な-adj + かもしれない (no だ): [雨|あめ]かもしれない', notes: 'Says something is possible, around fifty-fifty. It is weaker than でしょう (probably) and much weaker than はずだ (should be, g:hazu). In casual speech it shortens to かも. Nouns and な-adjectives join it directly, without だ.', examples: ['s:own:n4-kamo-shirenai-yuki', 's:tatoeba:2363874', 's:tatoeba:234338', 's:tatoeba:8897204'], ref: ['～かもしれない'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/kamoshiremasen-genki-ii-chapter-14/'], verified: true },
  { id: 'g:hazu', kind: 'grammar', level: 'N4', hl: ['(はず)(?=だ|です|じゃ|では)'], pattern: '〜はずだ/〜はずです', meaning: 'should be ~; is expected to ~ (a conclusion from facts you know)', formation: 'Plain form + はずだ; N + の + はずだ; な-adj + な + はずだ', notes: 'States what ought to be true, judging from what you know: バスはすぐ[来|く]るはずです "the bus should come soon (it\'s on the timetable)". It is a judgment, not advice: "you should do it" is 〜たほうがいい. It is stronger than かもしれない (g:kamo-shirenai). The negative "can\'t be" is はずがない (g:hazu-ga-nai).', examples: ['s:tatoeba:198131', 's:tatoeba:8579884', 's:tatoeba:11173182', 's:own:n4-hazu-tsuku'], ref: ['～はずです'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/hazudesu-genki-ii-chapter-19/'], verified: true },
  { id: 'g:hazu-ga-nai', kind: 'grammar', level: 'N4', hl: ['(はず[がは](?:ない|ありません))'], pattern: '〜はずがない/〜はずがありません/〜はずはない', meaning: 'there is no way that ~; ~ can\'t be', formation: 'Plain form + はずがない (はずはない, polite はずがありません); N + の + はずがない', notes: 'A strong denial based on what you know: [先生|せんせい]がそんなことを[言|い]ったはずがない "the teacher can\'t have said that". Compare 〜ないはずだ, "should not ~", which is a milder expectation. Built on はず (g:hazu).', examples: ['s:tatoeba:141784', 's:tatoeba:11692639', 's:tatoeba:81586', 's:own:n4-hazu-ga-nai-shiranai'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list はずがない at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%AF%E3%81%9A%E3%81%8C%E3%81%AA%E3%81%84', 'https://japanesetest4you.com/flashcard/learn-japanese-grammar-49/'], verified: true },
  { id: 'g:yotei-da', kind: 'grammar', level: 'N4', hl: ['(よてい)(?=だ|です|な)'], pattern: '〜よていだ/〜よていです (予定)', meaning: 'be scheduled to ~; plan to ~', formation: 'V (dictionary form) + よていだ; N + の + よていだ ([予定|よてい] is written in kana here: [予|よ] and [定|てい] are N3 kanji)', notes: 'States a fixed plan or timetable: バスは[九|く][時|じ]に[着|つ]くよていです. It sounds more settled than つもり (N5 g:tsumori), which is only your own intention. It can describe other people\'s or official plans too.', examples: ['s:own:n4-yotei-da-natsuyasumi', 's:own:n4-yotei-da-basu', 's:own:n4-yotei-da-kaigi'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list 予定だ at N4', sources: ['https://bunpro.jp/grammar_points/%E3%82%88%E3%81%A6%E3%81%84%E3%81%A0', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%82%88%e3%81%a6%e3%81%84%e3%81%a0-yotei-da/'], verified: true },
  { id: 'g:potential', kind: 'grammar', level: 'N4', hl: ['(られ)(?=る|ます|ない|ません|なかった)', '(?<=[話読書行飲使待泳歌作走買帰入言会持立])([せめけてえれげ])(?=る|ます|ない|ません|なかった)'], pattern: 'V-える / V-られる (potential form)', meaning: 'can ~, be able to ~', formation: 'る-verbs: る → られる ([食|た]べられる); う-verbs: last u-sound → e-sound + る ([話|はな]す → [話|はな]せる, [読|よ]む → [読|よ]める, [行|い]く → [行|い]ける); する → できる, [来|く]る → [来|こ]られる (こられる)', notes: 'The potential form is itself a る-verb ([話|はな]せます, [話|はな]せない). The thing you can do usually takes が instead of を: [日本|にほん][語|ご]が[話|はな]せる. In casual speech る-verbs often drop ら ([食|た]べれる), but write られる. For る-verbs the form looks like the passive (g:passive, later): context tells them apart. 〜ことができる (g:koto-ga-dekiru) says the same more formally. [分|わ]かる, [見|み]える, [聞|き]こえる already contain "can" and have no potential form of their own.', examples: ['s:own:n4-potential-nihongo', 's:own:n4-potential-korareru', 's:tatoeba:158343', 's:tatoeba:226787', 's:tatoeba:10903672', 's:tatoeba:220973'], offList: 'conjugation form, not a Tanos pattern (Tanos ～られる is read as the passive); Bunpro + japanesetest4you list the potential at N4, Genki II ch.13', conjForm: 'potential', sources: ['https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/potential-verbs-genki-ii-chapter-13/', 'https://bunpro.jp/grammar_points/Verb%5Bpotential%5D', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%82%89%e3%82%8c%e3%82%8b-rareru-1/'], verified: true },
  { id: 'g:koto-ga-dekiru', kind: 'grammar', level: 'N4', hl: ['(ことが(?:でき|出来))'], pattern: '〜ことができる', meaning: 'can ~, be able to ~ (formal)', formation: 'V (dictionary form) + ことができる (polite ことができます; past ことができた)', notes: 'Means the same as the potential form (g:potential) but sounds more formal and is common in notices and writing: ここで[勉強|べんきょう]することができます. It is also the easy route for long verbs. It can say a thing is possible or allowed, not only a personal skill. Built on こと (g:koto).', examples: ['s:tatoeba:3456433', 's:tatoeba:11013888', 's:tatoeba:10326041', 's:own:n4-koto-ga-dekiru-oyogu'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list ことができる at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%93%E3%81%A8%E3%81%8C%E3%81%A7%E3%81%8D%E3%82%8B', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%93%e3%81%a8%e3%81%8c%e3%81%a7%e3%81%8d%e3%82%8b-koto-ga-dekiru/'], verified: true },
  { id: 'g:yasui', kind: 'grammar', level: 'N4', hl: ['(?<=[きぎしちにびみりいべけせてねめれえ])(やす)(?=い|く|かった)'], pattern: '〜やすい', meaning: 'easy to ~', formation: 'V-ます stem + やすい (conjugates like an い-adjective: [読|よ]みやすい, [読|よ]みやすくない)', notes: 'Says an action is easy to do: このペンは[書|か]きやすい. It attaches to the ます-stem, so [読|よ]みやすい "easy to read" is not [安|やす]い "cheap". The opposite is 〜にくい (g:nikui). It can also mean "tends to ~": こわれやすい "breaks easily".', examples: ['s:own:n4-yasui-pen', 's:tatoeba:206661', 's:tatoeba:9963851', 's:tatoeba:10563891'], ref: ['～やすい'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/yasui-nikui-genki-ii-chapter-20/'], verified: true },
  { id: 'g:nikui', kind: 'grammar', level: 'N4', hl: ['(?<=[きぎしちにびみりいべけせてねめれえ])(にく)(?=い|く|かった)'], pattern: '〜にくい', meaning: 'hard to ~', formation: 'V-ます stem + にくい (conjugates like an い-adjective: [読|よ]みにくい, [読|よ]みにくかった)', notes: 'Says an action is hard to do because of the thing or the situation: この[字|じ]は[読|よ]みにくい. The opposite of 〜やすい (g:yasui). 〜づらい is close, but leans toward the speaker finding it hard, even painful, to do.', examples: ['s:own:n4-nikui-kanji', 's:tatoeba:221479', 's:tatoeba:8650986'], ref: ['～にくい'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/yasui-nikui-genki-ii-chapter-20/'], verified: true },
  { id: 'g:kata', kind: 'grammar', level: 'N4', hl: ['(?<=[きしみびりいべえけぎちにせてめれ])(方)(?=[をがはもで、。]|$)'], pattern: '〜方 (かた)', meaning: 'the way of ~ing, how to ~', formation: 'V-ます stem + [方|かた]: [使|つか]い[方|かた], [作|つく]り[方|かた], [書|か]き[方|かた]; する-verb nouns: N + の + し[方|かた] ([勉強|べんきょう]のし[方|かた]). The object takes の: [時間|じかん]の[使|つか]い[方|かた]', notes: 'Turns a verb into "the way to do it": これの[使|つか]い[方|かた] "how to use this". Because the result is a noun, the object takes の, not を: [漢字|かんじ]の[書|か]き[方|かた]. Read [方|かた] as かた here; ほう (as in ほうがいい) is a different word.', examples: ['s:own:n4-kata-kippu', 's:tatoeba:10565932', 's:tatoeba:7427294', 's:tatoeba:2728130'], offList: 'not on Tanos N4 or the JLPT Sensei N4 list; Bunpro + japanesetest4you list かた at N4, Genki II ch.23', sources: ['https://bunpro.jp/grammar_points/%E3%81%8B%E3%81%9F', 'https://japanesetest4you.com/flashcard/learn-japanese-grammar-45/', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/kara-explanation-within-sentence-genki-i-chapter-9-2/'], verified: true },
  { id: 'g:te-ageru', kind: 'grammar', level: 'N4', hl: ['([てで]あげ)'], pattern: '〜てあげる', meaning: 'do ~ for someone (as a favour)', formation: 'V-て + あげる (polite あげます); the person helped takes に, or の for something of theirs: [妹|いもうと]に[本|ほん]を[読|よ]んであげた', notes: 'Used when you (or your side) do something for someone else. Saying it straight to the person can sound like you are doing them a big favour, so offers often use 〜ましょうか instead ([持|も]ちましょうか). For favours that come to you, use 〜てくれる (g:te-kureru).', examples: ['s:own:n4-te-ageru-imouto', 's:tatoeba:8586214', 's:tatoeba:1233763', 's:tatoeba:9891143'], ref: ['～てあげる'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/tekureruagerumorau-genki-ii-chapter-16/'], verified: true },
  { id: 'g:te-kureru', kind: 'grammar', level: 'N4', hl: ['([てで]くれ)(?=る|た|ます|ました|ない|ません)'], pattern: '〜てくれる', meaning: 'someone does ~ for me (or for us)', formation: 'V-て + くれる (polite くれます); the giver is the subject: [父|ちち]が[本|ほん]を[買|か]ってくれた', notes: 'The favour comes toward the speaker or the speaker\'s side, and it shows thanks: [父|ちち]が[本|ほん]を[買|か]ってくれた "my father bought me a book (kindly)". As a question, 〜てくれる？ / 〜てくれませんか is a request. When you do the favour, use 〜てあげる (g:te-ageru).', examples: ['s:own:n4-te-kureru-keeki', 's:tatoeba:9037336', 's:tatoeba:10642319', 's:tatoeba:123567'], ref: ['～てくれる'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/tekureruagerumorau-genki-ii-chapter-16/'], verified: true },
  { id: 'g:te-morau', kind: 'grammar', level: 'N4', hl: ['([てで]もら)'], pattern: '〜てもらう', meaning: 'have someone do ~ for me; get someone to do ~', formation: 'Person + に + V-て + もらう (polite もらいます): [母|はは]に[料理|りょうり]を[教|おし]えてもらった', notes: 'The receiver is the subject and the helper takes に: [母|はは]に[教|おし]えてもらった "I had my mother teach me". It is the same event as [母|はは]が[教|おし]えてくれた, seen from the receiver\'s side. 〜てもらえませんか is a polite request; ていただく is the humble version (g:te-itadakemasen-ka).', examples: ['s:own:n4-te-morau-shashin', 's:tatoeba:10982438', 's:tatoeba:227939', 's:tatoeba:11053931'], ref: ['～てもらう'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/tekureruagerumorau-genki-ii-chapter-16/'], verified: true },
  { id: 'g:te-kurete-arigatou', kind: 'grammar', level: 'N4', hl: ['([てで]くれて)(?=ありがとう)'], pattern: '〜てくれてありがとう', meaning: 'thank you for doing ~', formation: 'V-て + くれて + ありがとう; polite: V-て + くださって + ありがとうございます', notes: 'Thanks someone for a specific thing they did for you: [本|ほん]を[貸|か]してくれてありがとう. It is casual, for friends and family; to a teacher or a customer use 〜てくださってありがとうございます. It is built on 〜てくれる (g:te-kureru).', examples: ['s:tatoeba:8579832', 's:tatoeba:167138', 's:tatoeba:8619684', 's:own:n4-te-kurete-arigatou-tetsudau'], ref: ['～てくれてありがとう'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/kuretearigato-genki-ii-chapter-19/'], verified: true },
  { id: 'g:te-itadakemasen-ka', kind: 'grammar', level: 'N4', hl: ['([てで]いただけ(?:ません|ます)か)'], pattern: '〜ていただけませんか', meaning: 'could you possibly ~? (a very polite request)', formation: 'V-て + いただけませんか (いただく "receive", humble, in its potential form); softer: いただけないでしょうか', notes: 'Literally "can I not receive your doing ~?", which makes it one of the most polite everyday requests: [少|すこ]し[待|ま]っていただけませんか. Use it with teachers, strangers and customers. Going down in politeness: 〜てもらえませんか, 〜てくれませんか, 〜てください. The ending いただけますか is a little less soft.', examples: ['s:tatoeba:146797', 's:tatoeba:201800', 's:tatoeba:148943', 's:own:n4-te-itadakemasen-ka-michi'], ref: ['～ていただけませんか'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/teitadakemasen-genki-ii-chapter-16/'], verified: true },
  { id: 'g:te-sumimasen', kind: 'grammar', level: 'N4', hl: ['([てで](?:すみません|ごめん))'], pattern: '〜てすみません/〜てごめん', meaning: 'sorry for ~ing', formation: 'V-て + すみません (past: すみませんでした); not doing: V-ない → なくて + すみません; N + で + すみません', notes: 'Apologises for a specific thing you did: おそくなってすみません "sorry I\'m late". For something you failed to do, use なくて (g:nakute): [電話|でんわ]しなくてすみませんでした. With friends, 〜てごめん(ね) is the casual version.', examples: ['s:own:n4-te-sumimasen-osoku', 's:own:n4-te-sumimasen-denwa', 's:tatoeba:11871026', 's:tatoeba:10193298'], ref: ['～てすみません'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/te-sumimasen-deshita-genki-ii-chapter-16/'], verified: true },
  { id: 'g:te-yokatta', kind: 'grammar', level: 'N4', hl: ['([てで]よかった)'], pattern: '〜てよかった', meaning: 'I\'m glad (that) ~; it was good that ~', formation: 'V-て + よかった (polite よかったです); N / な-adj + で + よかった; not: なくてよかった', notes: 'Expresses relief or gladness about something that happened: [来|き]てよかった "I\'m glad I came". Compare 〜ばよかった (g:ba-yokatta, later), "I wish I had ~", regret about something that did not happen.', examples: ['s:own:n4-te-yokatta-daigaku', 's:tatoeba:11935865', 's:tatoeba:11924394', 's:tatoeba:11481787'], ref: ['～てよかった'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/teyokattadesu-genki-ii-chapter-19/'], verified: true },
  { id: 'g:jidoushi-tadoushi', kind: 'grammar', level: 'N4', hl: ['([がを])(?=(?:開|始|止|閉|つけ|つき|きえ|けし))'], pattern: 'Vi / Vt (intransitive and transitive pairs)', meaning: 'verb pairs for "it opens" vs "someone opens it" (intransitive vs transitive)', formation: 'Intransitive: N が Vi (ドアが[開|あ]く, [電気|でんき]がつく, じゅぎょうが[始|はじ]まる); transitive: (Person が) N を Vt (ドアを[開|あ]ける, [電気|でんき]をつける, じゅぎょうを[始|はじ]める)', notes: 'Many verbs come in pairs. The intransitive one says what happens to the thing, with が: ドアが[開|あ]きました "the door opened". The transitive one says someone does it to the thing, with を: ドアを[開|あ]けました "I opened the door". Common pairs: [開|あ]く / [開|あ]ける, [始|はじ]まる / [始|はじ]める, [止|と]まる / [止|と]める, つく / つける, きえる / けす. The pair matters for 〜ている (ドアが[開|あ]いている, a state) and 〜てある (ドアが[開|あ]けてある, g:te-aru).', examples: ['s:own:n4-jita-aku', 's:tatoeba:13356118', 's:own:n4-jita-hajimaru', 's:own:n4-jita-hajimeru', 's:tatoeba:11253962'], offList: 'not on Tanos N4; japanesetest4you lists transitive / intransitive verbs at N4, Genki II ch.18', sources: ['https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-transitive-intransitive-verbs/', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/transitive-pairs-genki-ii-chapter-18/'], verified: true },
  { id: 'g:te-aru', kind: 'grammar', level: 'N4', hl: ['([てで]あ(?:る|り|っ))'], pattern: '〜てある', meaning: 'has been done (and the result is still there, done on purpose)', formation: 'N + が + Vt-て + ある (transitive verbs): まどが[開|あ]けてある, [名前|なまえ]が[書|か]いてある', notes: 'Describes a state that someone created on purpose: まどが[開|あ]けてあります "the window has been opened (and left open)". Compare 〜ている with an intransitive verb, which just describes the state: まどが[開|あ]いています "the window is open". The thing takes が (or は), and the person who did it is not mentioned. Only transitive verbs (g:jidoushi-tadoushi) take てある.', examples: ['s:own:n4-te-aru-mado', 's:own:n4-te-aru-hana', 's:tatoeba:10901490', 's:tatoeba:10286281'], ref: ['～てある'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/tearu-genki-ii-chapter-21/'], verified: true },
  { id: 'g:te-oku', kind: 'grammar', level: 'N4', hl: ['([てで]お(?:く|き|い|か|こ))'], pattern: '〜ておく', meaning: 'do ~ in advance (to be ready); leave something as it is', formation: 'V-て + おく (polite おきます; casual 〜とく: [買|か]っとく)', notes: 'You do something now with a later need in mind: パーティーの[前|まえ]に[飲|の]み[物|もの]を[買|か]っておきます "I\'ll buy drinks before the party". It also means leaving a state as it is: まどを[開|あ]けておいて "leave the window open". [考|かんが]えておきます "I\'ll think about it" is a common polite way to put off an answer.', examples: ['s:own:n4-te-oku-nomimono', 's:tatoeba:173470', 's:tatoeba:9930912', 's:tatoeba:79947'], ref: ['～ておく'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/teoku-genki-ii-chapter-15/'], verified: true },
  { id: 'g:te-shimau', kind: 'grammar', level: 'N4', hl: ['([てで]しま(?:う|っ|い|わ))', '((?:ちゃ|じゃ)(?:う|っ))'], pattern: '〜てしまう/〜ちゃう/〜じゃう', meaning: 'do ~ completely; end up doing ~ (often with regret)', formation: 'V-て + しまう (past しまった); casual: 〜てしまう → 〜ちゃう, 〜でしまう → 〜じゃう ([食|た]べちゃった, [飲|の]んじゃった)', notes: 'Two feelings share one form. "All done": この[本|ほん]はもう[読|よ]んでしまいました. "Oops / too bad": さいふをなくしてしまった "I (went and) lost my wallet". Context, and often the past tense, tells you which. In conversation it is almost always ちゃう / じゃう.', examples: ['s:own:n4-te-shimau-saifu', 's:own:n4-te-shimau-hon', 's:tatoeba:198118', 's:tatoeba:84418', 's:own:n4-te-shimau-keeki'], ref: ['～てしまう'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/teshimau-genki-ii-chapter-18/'], verified: true },
  { id: 'g:te-miru', kind: 'grammar', level: 'N4', hl: ['([てで]み(?:る|た|ます|まし|よう|て))'], pattern: '〜てみる', meaning: 'try doing ~ (and see what it is like)', formation: 'V-て + みる (a る-verb: てみます, てみた, てみたい)', notes: 'You do something to find out how it goes: [着|き]てみてもいいですか "may I try it on?". It is not "attempt something hard" (that is 〜ようとする, N3). Written in kana, because みる here is not really "see". 〜てみたい "I\'d like to try ~" is very common.', examples: ['s:own:n4-te-miru-fuku', 's:own:n4-te-miru-sensei', 's:tatoeba:3509628', 's:tatoeba:10032516'], ref: ['てみる'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/temiru-genki-ii-chapter-13/'], verified: true },
  { id: 'g:te-iku', kind: 'grammar', level: 'N4', hl: ['([てで](?:い|行)(?:く|き|っ|か))'], pattern: '〜ていく', meaning: 'go ~ing / do ~ and go; (a change) goes on from now', formation: 'V-て + いく (usually kana; [行|い]って[行|い]く is avoided): [歩|ある]いていく, [持|も]っていく, なっていく', notes: 'Movement away from the speaker or the present: [駅|えき]まで[歩|ある]いていきます "I\'ll walk to the station", かさを[持|も]っていく "take an umbrella (with me)". With change verbs it means the change will continue from now on: [寒|さむ]くなっていく. Its mirror is 〜てくる (g:te-kuru).', examples: ['s:own:n4-te-iku-kasa', 's:tatoeba:10983063', 's:tatoeba:152713', 's:own:n4-te-iku-samuku'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list ていく at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%A6%E3%81%84%E3%81%8F', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%a6%e3%81%84%e3%81%8f-te-iku/'], verified: true },
  { id: 'g:te-kuru', kind: 'grammar', level: 'N4', hl: ['([てで](?:く|き|来)(?:る|た|ます|まし|て))'], pattern: '〜てくる/〜てきた/〜てきます', meaning: 'go and do ~ (and come back); come ~ing; (a change) has begun / has been going on', formation: 'V-て + くる (usually kana): [借|か]りてくる, [持|も]ってきた, なってきた', notes: 'Movement toward the speaker: [花|はな]を[持|も]ってきた "I brought flowers". It also means "go, do, and come back": [車|くるま]を[借|か]りてくるよ. With change verbs it shows a change that has started or built up until now: [明|あか]るくなってきた "it has started to get light", [雨|あめ]がふってきた "it\'s started to rain". Compare 〜ていく (g:te-iku), from now on.', examples: ['s:own:n4-te-kuru-ame', 's:tatoeba:11527664', 's:own:n4-te-kuru-pan', 's:tatoeba:8588370'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list てくる at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%A6%E3%81%8F%E3%82%8B', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%a6%e3%81%8f%e3%82%8b-te-kuru/'], verified: true },
  { id: 'g:stem-compounds', kind: 'grammar', level: 'N4', hl: ['(?<=[きしみびりいべえけぎちにせてめれ])(始め|はじめ|終わ|おわ|続け|つづけ|出し|だし|出す|だす)'], pattern: '〜始める/〜終わる/〜つづける/〜出す', meaning: 'start ~ing / finish ~ing / keep ~ing / suddenly start ~ing', formation: 'V-ます stem + [始|はじ]める ([読|よ]み[始|はじ]める), [終|お]わる ([食|た]べ[終|お]わる), [続|つづ]ける (ふりつづける, [続|つづ] written in kana at N4), [出|だ]す ([走|はし]り[出|だ]す)', notes: 'The ます-stem joins a second verb that adds the phase: [読|よ]み[始|はじ]める "start reading", [食|た]べ[終|お]わる "finish eating", [待|ま]ちつづける "keep waiting". 〜[出|だ]す is a sudden start, often something not planned: [雨|あめ]がふり[出|だ]した "it suddenly began to rain". The compound conjugates like its second verb.', examples: ['s:own:n4-stem-compounds-tsuzukeru', 's:tatoeba:4359202', 's:tatoeba:11340615', 's:tatoeba:160640'], offList: 'not on Tanos N4 (Tanos lists ～始める at N3); Bunpro lists はじめる / おわる / つづける / だす at N4, japanesetest4you all four at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%AF%E3%81%98%E3%82%81%E3%82%8B', 'https://bunpro.jp/grammar_points/%E3%81%8A%E3%82%8F%E3%82%8B', 'https://bunpro.jp/grammar_points/%E3%81%A4%E3%81%A5%E3%81%91%E3%82%8B', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%e3%81%a0%e3%81%99-dasu/'], verified: true },
  // ── Blocks 8-14: time, conditionals, intention, obligation, voice, keigo ──
  { id: 'g:ato-de', kind: 'grammar', level: 'N4', hl: ['((?:後|あと)で)'], pattern: '〜後で/あとで', meaning: 'after ~; later', formation: 'V-た + [後|あと]で ([食|た]べた[後|あと]で); N + の + [後|あと]で (じゅぎょうの[後|あと]で); [後|あと]で alone = "later"', notes: 'The verb before [後|あと]で is always in the た-form, even when the whole sentence is about the future: [食|た]べた[後|あと]で、さんぽします. On its own, [後|あと]で just means "later": また[後|あと]で. 〜てから (g:te-kara) also orders two actions, but it stresses that the second follows straight on from the first; [後|あと]で only says which came first.', examples: ['s:own:n4-ato-de-sanpo', 's:own:n4-ato-de-jugyou', 's:tatoeba:10914867', 's:tatoeba:3024537'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list あとで at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%82%E3%81%A8%E3%81%A7', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%82%E3%81%A8%E3%81%A7-ato-de/'], verified: true },
  { id: 'g:made-ni', kind: 'grammar', level: 'N4', pattern: '〜までに', meaning: 'by (a deadline); before ~ at the latest', formation: 'Time N + までに ([金曜日|きんようび]までに); V (dictionary form) + までに ([帰|かえ]るまでに)', notes: 'までに sets a deadline: the action happens at some point before that time. Plain まで (g:made) means "until" and covers the whole stretch: [五|ご][時|じ]まで[働|はたら]く "work until five" but [五|ご][時|じ]までに[帰|かえ]る "be home by five". The verb after まで goes on; the verb after までに happens once.', examples: ['s:own:n4-made-ni-shukudai', 's:own:n4-made-ni-kaeru', 's:tatoeba:232004', 's:tatoeba:175607'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list までに at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%BE%E3%81%A7%E3%81%AB', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%BE%E3%81%A7%E3%81%AB/'], verified: true },
  { id: 'g:goro', kind: 'grammar', level: 'N4', pattern: '〜ごろ', meaning: 'around, about (a point in time)', formation: 'Time N + ごろ (+ に): [六|ろく][時|じ]ごろ, [三月|さんがつ]ごろ', notes: 'ごろ makes a point in time approximate: [七|しち][時|じ]ごろ[起|お]きます "I get up around seven". Use it with clock times, dates and seasons; for amounts and lengths of time use ぐらい instead ([一|いち][時|じ][間|あいだ]ぐらい "about an hour"). に after ごろ is optional. The kanji [頃|ころ] is above N4, so write ごろ in kana.', examples: ['s:own:n4-goro-neru', 's:tatoeba:187461', 's:tatoeba:11241491', 's:own:n4-goro-kaeru'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list ごろ at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%94%E3%82%8D', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%94%E3%82%8D-goro/'], verified: true },
  { id: 'g:ni-frequency', kind: 'grammar', level: 'N4', hl: ['(に[一二三四五六七八九十何]+(?:度|回|かい))'], pattern: '〜に〜度/〜回', meaning: '~ times per (week / month / year)', formation: 'Period + に + number + [度|ど] / [回|かい]: [週|しゅう]に[二|に][度|ど], [月|つき]に[一度|いちど], [一日|いちにち]に[三|さん][回|かい]', notes: 'に after a span of time divides it, giving a rate: [週|しゅう]に[一度|いちど] "once a week", [一日|いちにち]に[三|さん][回|かい] "three times a day". The period comes first, then に, then how many times. [度|ど] and [回|かい] both count times; [回|かい] is the more everyday word but its kanji is above N4, so this course writes [度|ど] or かい.', examples: ['s:own:n4-ni-frequency-puuru', 's:tatoeba:1174310', 's:tatoeba:1085893', 's:tatoeba:9200773'], ref: ['(period)に(frequency)'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/frequency-of-events-over-a-period-of-time-genki-ii-chapter-13/'], verified: true },
  { id: 'g:nagara', kind: 'grammar', level: 'N4', hl: ['(?<=[いきしちにびみりぎえけべめれせ])(ながら)'], pattern: '〜ながら', meaning: 'while ~ing (doing two things at once)', formation: 'V-ます stem + ながら: [聞|き]きながら, [食|た]べながら, しながら', notes: 'One person does two things at the same time. The main action comes last; the ながら verb is the background: [音楽|おんがく]を[聞|き]きながら[勉強|べんきょう]します "I study while listening to music". The ながら verb takes no tense of its own. When two different people are involved, use 〜ている[間|あいだ]に (g:te-iru-aida-ni) instead.', examples: ['s:own:n4-nagara-ongaku', 's:tatoeba:11765971', 's:tatoeba:81619', 's:tatoeba:166551'], ref: ['～ながら'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/nagara-genki-ii-chapter-18/'], verified: true },
  { id: 'g:te-iru-aida-ni', kind: 'grammar', level: 'N4', hl: ['((?:間|あいだ)に)'], pattern: '〜間に/あいだに', meaning: 'while ~ (is going on), something happens', formation: 'V-ている + [間|あいだ]に (ねている[間|あいだ]に); N + の + [間|あいだ]に ([夏休|なつやす]みの[間|あいだ]に); いる + [間|あいだ]に', notes: 'X [間|あいだ]に Y: during the time X lasts, Y happens once, at some point in it. Without に, [間|あいだ] means Y fills the whole time: [待|ま]っている[間|あいだ]、[本|ほん]を[読|よ]んでいた. The two parts can have different subjects ([母|はは]がねている[間|あいだ]に、[私|わたし]が[作|つく]った), which ながら (g:nagara) cannot. The verb before [間|あいだ] stays in the ている / いる form, even in the past.', examples: ['s:own:n4-aida-ni-haha', 's:own:n4-aida-ni-nihon', 's:tatoeba:8720976', 's:tatoeba:338061'], ref: ['～ているあいだに,～'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/aidani-genki-ii-chapter-21/'], verified: true },
  { id: 'g:tokoro-da', kind: 'grammar', level: 'N4', hl: ['(ところ)(?=だ|です|でし)'], pattern: '〜ところだ/〜ところです', meaning: 'be just about to ~ / be in the middle of ~ing / have just ~ed', formation: 'V (dictionary) + ところだ: about to; V-ている + ところだ: in the middle of; V-た + ところだ: just did', notes: 'ところ here means "point in time", and the verb form before it picks the moment: [出|で]るところです "I\'m just about to leave", [書|か]いているところです "I\'m (right in the middle of) writing", [帰|かえ]ったところです "I\'ve just got back". It answers "what are you doing right now?". Not the same as ところ "place" (いいところ).', examples: ['s:own:n4-tokoro-deru', 's:tatoeba:157026', 's:tatoeba:172862', 's:tatoeba:203585'], offList: 'not on Tanos N4; Bunpro lists るところだ / ているところだ / たところだ at N4, japanesetest4you ところ / ているところ / たところ at N4', sources: ['https://bunpro.jp/grammar_points/%E3%82%8B%E3%81%A8%E3%81%93%E3%82%8D%E3%81%A0', 'https://bunpro.jp/grammar_points/%E3%81%A6%E3%81%84%E3%82%8B%E3%81%A8%E3%81%93%E3%82%8D%E3%81%A0', 'https://bunpro.jp/grammar_points/%E3%81%9F%E3%81%A8%E3%81%93%E3%82%8D%E3%81%A0', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%A8%E3%81%93%E3%82%8D-tokoro/'], verified: true },
  { id: 'g:to-conditional', kind: 'grammar', level: 'N4', hl: ['(?<=[うくぐすつぬぶむるい])(と)(?=、)'], pattern: '〜と (dictionary form + と)', meaning: 'when / whenever ~, (then) …; if you ~, you will …', formation: 'V (dictionary form) + と; V-ない + と; い-adj + と; N / な-adj + だ + と', notes: 'X と Y says that Y follows from X automatically, every time: [春|はる]になると、[花|はな]がさく. It fits machines, nature, habits and directions ([右|みぎ]にまがると、[駅|えき]が[見|み]えます). Because the result just happens, the Y part cannot be a request, an invitation or "I will": for those use たら (g:tara). With a past ending it reports a discovery: [外|そと]に[出|で]ると、[雨|あめ]がふっていた.', examples: ['s:own:n4-to-botan', 's:own:n4-to-michi', 's:tatoeba:11038976', 's:tatoeba:11021414', 's:tatoeba:10932044'], ref: ['Dictionary form+と'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/to-genki-ii-chapter-18/'], verified: true },
  { id: 'g:to-ii', kind: 'grammar', level: 'N4', hl: ['(といい)'], pattern: '〜といい(です)', meaning: 'I hope ~; it would be good if ~; (advice) you should ~', formation: 'V (dictionary / ない form) + といい(です / な / ね); い-adj + といい; N / な-adj + だ + といい', notes: 'Says what you hope will happen, often with ね or な: あした、はれるといいですね "I hope it\'s sunny tomorrow". Ending with けど / んですが adds "…but I\'m not sure". Said to someone else, 〜といいですよ is gentle advice: "it\'s good to ~". Do not confuse it with 〜といいます "is called" (N5).', examples: ['s:own:n4-to-ii-hareru', 's:tatoeba:9809478', 's:tatoeba:10365237', 's:tatoeba:10989493', 's:tatoeba:11052418'], ref: ['～といいです'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/toii-genki-ii-chapter-16/'], verified: true },
  { id: 'g:tara', kind: 'grammar', level: 'N4', conjForm: 'たら-form', hl: ['(?<!あ)(たら|だら)'], pattern: '〜たら', meaning: 'if ~; when ~ (once it has happened), …', formation: 'V-た + ら ([行|い]ったら, [読|よ]んだら, [来|き]たら); V-なかった + ら; い-adj かったら; N / な-adj + だったら', notes: 'Make the た-form and add ら. X たら Y means Y comes after X is done: [駅|えき]に[着|つ]いたら、[電話|でんわ]してください "call me when you get to the station". It also covers ordinary "if": [雨|あめ]だったら、[行|い]きません. Unlike と (g:to-conditional) the Y part can be anything, including requests and plans, which makes たら the safest "if" in conversation.', examples: ['s:own:n4-tara-nihon', 's:own:n4-tara-eki', 's:tatoeba:10637887', 's:tatoeba:11284358', 's:tatoeba:889751'], ref: ['～たら'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/tara-genki-ii-chapter-17/'], verified: true },
  { id: 'g:tara-dou', kind: 'grammar', level: 'N4', hl: ['((?:た|だ)らどう)'], pattern: '〜たらどうですか/〜たらどう', meaning: 'why don\'t you ~? how about ~ing? (suggestion)', formation: 'V-た + らどうですか (polite) / らどう (casual): [休|やす]んだらどうですか', notes: 'A suggestion to the listener: "how would it be if you ~?". The polite でしょうか version is softer. It can sound a little pushy to someone above you, so with a teacher or boss 〜たほうがいいと[思|おも]います (g:hou-ga-ii) is safer. 〜たらどうなる / 〜たらどうしよう ask "what happens if" and are not suggestions.', examples: ['s:own:n4-tara-dou-kusuri', 's:tatoeba:146815', 's:tatoeba:194237', 's:tatoeba:189329', 's:tatoeba:9966058'], ref: ['～たらどうですか'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/tara-dodesuka-genki-ii-chapter-14/'], verified: true },
  { id: 'g:baai-wa', kind: 'grammar', level: 'N4', pattern: '〜場合は/ばあいは', meaning: 'in case of ~; if ~ (rules, instructions)', formation: 'N + の + [場合|ばあい]は ([雨|あめ]の[場合|ばあい]は); V (dictionary / ない / た form) + [場合|ばあい]は; い-adj / な-adj な + [場合|ばあい]は', notes: 'A formal way to say "if" or "in the event that", typical of rules, notices and instructions: じしんの[場合|ばあい]は、エレベーターを[使|つか]わないでください. The second part is usually what to do. In everyday talk たら (g:tara) is more natural. [合|あい] is above N4, so the word is written ばあい here.', examples: ['s:own:n4-baai-ame', 's:own:n4-baai-jishin', 's:own:n4-baai-yasumu', 's:own:n4-baai-wakaranai'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list 場合は at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%B0%E3%81%82%E3%81%84%E3%81%AF', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%B0%E3%81%82%E3%81%84%E3%81%AF-baai-wa/'], verified: true },
  { id: 'g:ba', kind: 'grammar', level: 'N4', conjForm: 'ば-form', hl: ['((?:[えけげせてねべめ]|れ)ば)(?!か)'], pattern: '〜ば/〜れば', meaning: 'if ~ (then …); provided that ~', formation: 'う-verbs: last sound to the え-row + ば ([行|い]けば, [飲|の]めば); る-verbs: る → れば ([食|た]べれば); する → すれば, [来|く]る → [来|く]れば; ない → なければ; い-adj: い → ければ ([安|やす]ければ, いい → よければ); N / な-adj + なら(ば)', notes: 'The ば-form puts the weight on the condition: if X holds, Y follows. It is common in advice and questions with いい: どうすればいいですか "what should I do?". Compared with たら (g:tara), ば is more about "on condition that" than "after"; compared with と (g:to-conditional), the Y part may be a wish or a plan when the X part is a state (お[金|かね]があれば、[買|か]いたい). It cannot report a one-off past event.', examples: ['s:own:n4-ba-kusuri', 's:tatoeba:10982400', 's:tatoeba:10637878', 's:tatoeba:8856423', 's:tatoeba:10083290'], ref: ['～ば/～れば'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/ba-genki-ii-chapter-22/'], verified: true },
  { id: 'g:ba-yokatta', kind: 'grammar', level: 'N4', hl: ['(ばよかった)'], pattern: '〜ばよかった', meaning: 'I should have ~; I wish I had ~ (regret)', formation: 'V-ば + よかった ([勉強|べんきょう]すればよかった); V-なければ + よかった (I shouldn\'t have): [食|た]べなければよかった', notes: 'Literally "it would have been good if I had ~", so it looks back at something that did not happen and wishes it had. Use the negative なければよかった for something you regret doing. Adding のに (g:noni) turns it into a complaint aimed at someone else: [言|い]ってくれればよかったのに "you should have told me".', examples: ['s:own:n4-ba-yokatta-benkyou', 's:tatoeba:226211', 's:tatoeba:193252', 's:tatoeba:11436390', 's:tatoeba:2280872'], ref: ['～ばよかった'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/bayokatta-desu-genki-ii-chapter-18/'], verified: true },
  { id: 'g:nara', kind: 'grammar', level: 'N4', pattern: '〜なら', meaning: 'if it\'s ~ (then); if (as you say) ~; as for ~', formation: 'N + なら (すしなら); V / い-adj (plain form) + なら ([行|い]くなら); な-adj + なら; often 〜んなら in speech', notes: 'なら picks up something just mentioned or given and says what follows from it: すしなら、あの[店|みせ]がいいですよ "if it\'s sushi (you want), that place is good". With a verb it can come before the action happens: [日本|にほん]へ[行|い]くなら、[春|はる]がいい "if you\'re going to Japan, spring is best", which たら (g:tara) cannot say. It also points out a topic someone asked about: トムなら、[外|そと]にいるよ.', examples: ['s:own:n4-nara-sushi', 's:tatoeba:80338', 's:tatoeba:10570281', 's:tatoeba:9440712', 's:tatoeba:12365439'], ref: ['なら'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/nara-genki-ii-chapter-13/'], verified: true },
  { id: 'g:te-mo', kind: 'grammar', level: 'N4', hl: ['((?:て|で)も)(?!いい|かまわ)'], pattern: '〜ても (〜でも)', meaning: 'even if ~; even though ~; no matter how ~', formation: 'V-て + も (ふっても, [読|よ]んでも); い-adj くても ([高|たか]くても); N / な-adj + でも ([雨|あめ]でも); V-なくても', notes: 'X ても Y: Y happens (or holds) whether or not X, against what you might expect: [雨|あめ]がふっても、[行|い]きます "I\'ll go even if it rains". With いくら or どんなに it means "no matter how much": いくら[考|かんが]えても、わかりません. Do not mix it up with 〜てもいい "may" (g:te-mo-ii, N5). のに (g:noni) is for a result that already disappointed you.', examples: ['s:own:n4-te-mo-ame', 's:own:n4-te-mo-takai', 's:tatoeba:6015', 's:tatoeba:10119936', 's:tatoeba:1488024'], ref: ['～ても'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/temo-genki-ii-chapter-23/'], verified: true },
  { id: 'g:noni', kind: 'grammar', level: 'N4', pattern: '〜のに', meaning: 'although ~, even though ~ (and the result is surprising or annoying)', formation: 'Plain form + のに ([勉強|べんきょう]したのに, [高|たか]いのに); N / な-adj + なのに ([日曜日|にちようび]なのに, しずかなのに)', notes: 'X のに Y: X is a fact, and Y is not what you would expect from it, often with surprise, regret or complaint: たくさん[勉強|べんきょう]したのに、テストはよくなかった. Nouns and な-adjectives take なのに. けど states a plain contrast; のに adds feeling. Unlike ても (g:te-mo), X has already happened. At the end of a sentence (〜ばよかったのに) it voices a regret or a wish.', examples: ['s:own:n4-noni-nichiyoubi', 's:own:n4-noni-tesuto', 's:tatoeba:10315190', 's:tatoeba:11273472'], ref: ['のに'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/noni-genki-ii-chapter-21/'], verified: true },
  { id: 'g:volitional', kind: 'grammar', level: 'N4', conjForm: 'volitional', hl: ['((?:[こごそとのぼもろお]|よ)う)(?=[。！？]|か|よ|と(?:思|おも))'], pattern: 'V-おう/V-よう (volitional form)', meaning: 'let\'s ~ (casual); I\'ll ~ (deciding on the spot)', formation: 'る-verbs: る → よう ([食|た]べよう, [見|み]よう); う-verbs: last sound to the お-row + う ([行|い]こう, [待|ま]とう, [飲|の]もう); する → しよう, [来|く]る → [来|こ]よう', notes: 'The plain form of 〜ましょう (g:mashou): [行|い]こう = [行|い]きましょう among friends. 〜ようか offers or asks "shall we / shall I?": [何|なん]か[食|た]べようか. Said to yourself it means "I\'ll ~": [電話|でんわ]をかけよう. It is also the base of 〜ようと[思|おも]う (g:you-to-omou).', examples: ['s:own:n4-volitional-eiga', 's:tatoeba:124815', 's:tatoeba:188264', 's:tatoeba:11070916', 's:tatoeba:228664', 's:tatoeba:124669'], ref: ['～よう', '～おう'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/volitional-form-genki-ii-chapter-15/', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-volitional-form/'], verified: true },
  { id: 'g:you-to-omou', kind: 'grammar', level: 'N4', hl: ['((?:[こごそとのぼもろお]|よ)うと)(?=思|おも)'], pattern: 'V-よう/V-おう と思う', meaning: 'I\'m thinking of ~ing; I intend to ~', formation: 'V (volitional) + と[思|おも]う / と[思|おも]っている: [行|い]こうと[思|おも]います, [作|つく]ろうと[思|おも]っています', notes: 'Volitional + と[思|おも]う tells someone what you plan to do. [思|おも]います sounds like a decision being made now; [思|おも]っています says it is a plan you have had for a while. つもりだ (g:tsumori) is a firmer intention. For other people use [思|おも]っている: [兄|あに]は[車|くるま]を[買|か]おうと[思|おも]っている.', examples: ['s:own:n4-you-to-omou-natsu', 's:tatoeba:184819', 's:tatoeba:193297', 's:tatoeba:11021427', 's:tatoeba:10868206'], offList: 'not on Tanos N4; Bunpro and japanesetest4you list ようと思う at N4 (Genki II ch.15 teaches it with the volitional)', sources: ['https://bunpro.jp/grammar_points/%E3%82%88%E3%81%86%E3%81%A8%E6%80%9D%E3%81%86-%E3%81%8A%E3%81%86%E3%81%A8%E6%80%9D%E3%81%86', 'https://japanesetest4you.com/flashcard/learn-japanese-grammar-44/', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/volitional-form-genki-ii-chapter-15/'], verified: true },
  { id: 'g:koto-ni-suru', kind: 'grammar', level: 'N4', hl: ['(ことに)(?=し|す)'], pattern: '〜ことにする/〜ことにした/〜ことにします', meaning: 'decide to ~', formation: 'V (dictionary form) + ことにする: [行|い]くことにした; V-ない + ことにする: [行|い]かないことにした', notes: 'You make the choice yourself: [車|くるま]を[買|か]うことにした "I decided to buy a car". It usually appears in the past (ことにした / ことにしました) to report a decision. 〜ことにしている describes a rule you keep for yourself ([毎朝|まいあさ][走|はし]ることにしている). A decision made for you by others is ことになる (N3).', examples: ['s:own:n4-koto-ni-suru-benkyou', 's:tatoeba:156129', 's:tatoeba:11852556', 's:tatoeba:8808582', 's:tatoeba:9826890'], ref: ['～ことにする'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/kotonisuru-genki-ii-chapter-23/'], verified: true },
  { id: 'g:nakereba-naranai', kind: 'grammar', level: 'N4', hl: ['(なければ)(?=なら|なり|いけ)'], pattern: '〜なければ(ならない/いけない)', meaning: 'must ~, have to ~', formation: 'V-ない → なければ + ならない / いけない ([行|い]かなければならない); polite なりません / いけません; past ならなかった', notes: 'Literally "if (I) don\'t ~, it won\'t do", built on the ば-form of ない (g:ba). It is the fuller, more formal cousin of 〜なくてはいけない / 〜なくちゃ (N5): use it in writing and polite speech. ならない sounds like a general rule or duty; いけない is more personal. The casual short form is 〜なきゃ.', examples: ['s:own:n4-nakereba-kusuri', 's:tatoeba:121503', 's:tatoeba:188838', 's:tatoeba:80523', 's:tatoeba:5185663'], offList: 'not on Tanos N4; Bunpro lists なければならない and なければいけない at N4, japanesetest4you both at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%AA%E3%81%91%E3%82%8C%E3%81%B0%E3%81%AA%E3%82%89%E3%81%AA%E3%81%84', 'https://bunpro.jp/grammar_points/%E3%81%AA%E3%81%91%E3%82%8C%E3%81%B0%E3%81%84%E3%81%91%E3%81%AA%E3%81%84', 'https://japanesetest4you.com/flashcard/learn-japanese-grammar-50/'], verified: true },
  { id: 'g:nakute-mo-ii', kind: 'grammar', level: 'N4', hl: ['(なくても)(?=いい|大丈夫|かまわ)'], pattern: '〜なくてもいい', meaning: 'don\'t have to ~, it\'s OK not to ~', formation: 'V-ない → なくて + もいい ([行|い]かなくてもいい); polite なくてもいいです', notes: 'The negative of 〜てもいい "may" (g:te-mo-ii, N5): "it\'s fine even if you don\'t". It is the usual answer to a "must I?" question: [行|い]かなければなりませんか。―いいえ、[行|い]かなくてもいいです. Don\'t confuse it with 〜なくてはいけない "must" (N5), which looks similar but means the opposite.', examples: ['s:own:n4-nakute-mo-ii-namae', 's:tatoeba:8732421', 's:tatoeba:3023061', 's:tatoeba:182548', 's:tatoeba:10124146'], ref: ['～なくてもいい'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/nakutemoiidesu-genki-ii-chapter-17/'], verified: true },
  { id: 'g:nai-de', kind: 'grammar', level: 'N4', hl: ['(ないで)(?!くだ|ほし|ね)'], pattern: '〜ないで', meaning: 'without ~ing; instead of ~ing', formation: 'V-ない + で: [食|た]べないで, [持|も]たないで, [行|い]かないで', notes: 'X ないで Y: you do Y without doing X, or do Y in place of X: [朝|あさ]ごはんを[食|た]べないで[学校|がっこう]へ[行|い]った "I went to school without eating breakfast". The same person does both. It is the form inside 〜ないでください (N5). 〜なくて (g:nakute) is different: it gives a reason or links a negative fact ("didn\'t …, so …").', examples: ['s:own:n4-nai-de-asagohan', 's:own:n4-nai-de-kasa', 's:tatoeba:156631', 's:tatoeba:9993257'], ref: ['～ないで'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/naide-genki-ii-chapter-20/'], verified: true },
  { id: 'g:nasai', kind: 'grammar', level: 'N4', hl: ['(なさい)'], pattern: '〜なさい', meaning: 'do ~ (a firm but gentle command)', formation: 'V-ます stem + なさい: [起|お]きなさい, [食|た]べなさい, [勉強|べんきょう]しなさい', notes: 'An order from someone with authority who is looking after you: parents to children, teachers to students, and written test instructions ([正|ただ]しいものをえらびなさい). It is kind in tone but not polite, so never use it to a superior or a stranger. Between equals people say 〜て or 〜てください instead.', examples: ['s:own:n4-nasai-te', 's:tatoeba:182972', 's:tatoeba:83322', 's:tatoeba:79943', 's:tatoeba:192757'], ref: ['～なさい'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/verb-stem-nasai-genki-ii-chapter-22/'], verified: true },
  { id: 'g:imperative', kind: 'grammar', level: 'N4', conjForm: 'imperative', hl: ['((?:[えけげせてねべめれ]|ろ|来い|こい))(?=[！。よ」、])'], pattern: 'V-え/V-ろ (imperative form)', meaning: 'do ~! (blunt command)', formation: 'う-verbs: last sound to the え-row ([行|い]け, [待|ま]て, [止|と]まれ); る-verbs: る → ろ ([食|た]べろ, [起|お]きろ); する → しろ, [来|く]る → [来|こ]い (こい)', notes: 'The bare command form. In real life it is rough and mostly heard from men among close friends, in sports cheering (がんばれ！), in emergencies, and on signs and road markings ([止|と]まれ "STOP"). You need to recognise it, especially in quotes and signs, more than use it. A polite request is 〜てください (N5); a parent\'s order is 〜なさい (g:nasai).', examples: ['s:own:n4-imperative-sign', 's:own:n4-imperative-ganbare', 's:tatoeba:4443360', 's:tatoeba:140535', 's:tatoeba:184886', 's:tatoeba:195365'], offList: 'form point, not a Tanos pattern; Bunpro lists 命令形 at N4; Tae Kim teaches the command form; needed to read signs (止まれ)', sources: ['https://bunpro.jp/grammar_points/%E5%91%BD%E4%BB%A4%E5%BD%A2', 'https://guidetojapanese.org/learn/grammar/requests'], verified: true },
  { id: 'g:na-prohibitive', kind: 'grammar', level: 'N4', hl: ['(?<=[うくぐすつぬぶむる])(な)(?=[！。」]|よ)'], pattern: 'V-る な (prohibitive)', meaning: 'don\'t ~! (blunt prohibition)', formation: 'V (dictionary form) + な: [行|い]くな, [食|た]べるな, するな, [来|く]るな', notes: 'The negative partner of the imperative (g:imperative): dictionary form + な. Like the imperative it is rough in speech, and common on signs and in rules (ここに[入|はい]るな "keep out"). The sentence-final な after an adjective ([高|たか]いな "it\'s expensive, huh") is a different word; this one only follows a verb in dictionary form. The polite version is 〜ないでください (N5).', examples: ['s:own:n4-na-sign', 's:tatoeba:224594', 's:tatoeba:5072721', 's:tatoeba:164115', 's:tatoeba:10903600'], offList: 'form point, not a Tanos pattern; JLPT Sensei lists な at N4, Bunpro at N5 (so at or below N4); Tae Kim teaches it as the negative command', sources: ['jlptsensei', 'https://bunpro.jp/grammar_points/%E3%81%AA', 'https://guidetojapanese.org/learn/grammar/requests'], verified: true },
  { id: 'g:hitsuyou', kind: 'grammar', level: 'N4', pattern: '〜必要/ひつよう', meaning: 'is needed; need to ~', formation: 'N + が[必要|ひつよう]だ (パスポートが[必要|ひつよう]です); V (dictionary form) + [必要|ひつよう]がある / [必要|ひつよう]はない', notes: '[必要|ひつよう] is a noun, "necessity". With a thing: Nが[必要|ひつよう]です "N is needed". With an action: 〜する[必要|ひつよう]があります "it is necessary to ~", and 〜する[必要|ひつよう]はありません "there\'s no need to ~", which is close to 〜なくてもいい (g:nakute-mo-ii) but more formal. [必|ひつ] and [要|よう] are above N4, so it is written ひつよう here.', examples: ['s:own:n4-hitsuyou-nihongo', 's:own:n4-hitsuyou-pasupooto', 's:own:n4-hitsuyou-kaku', 's:own:n4-hitsuyou-hayaku'], offList: 'not on Tanos N4; Bunpro lists がひつよう and ひつようがある at N4, japanesetest4you 必要 / 必要がある at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%8C%E3%81%B2%E3%81%A4%E3%82%88%E3%81%86', 'https://bunpro.jp/grammar_points/%E3%81%B2%E3%81%A4%E3%82%88%E3%81%86%E3%81%8C%E3%81%82%E3%82%8B', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%B2%E3%81%A4%E3%82%88%E3%81%86%E3%81%8C%E3%81%82%E3%82%8B-hitsuyou-ga-aru/'], verified: true },
  { id: 'g:ku-ni-suru', kind: 'grammar', level: 'N4', hl: ['(く|に)(?=して|しま|する|しな|した|しろ)'], pattern: '〜くする/〜にする/〜くして/〜にして', meaning: 'make (something) ~; turn ~ up / down', formation: 'い-adj: い → く + する ([大|おお]きくする, [小|ちい]さくする); な-adj / N + に + する (きれいにする, しずかにする)', notes: 'The する partner of 〜くなる / 〜になる (g:naru, N5): なる is "become" (it changes by itself), する is "make" (someone changes it): [音|おと]が[大|おお]きくなった "it got louder" vs [音|おと]を[大|おお]きくした "I turned it up". The thing changed takes を. Note: N + にする can also mean "decide on" (コーヒーにします), a separate use.', examples: ['s:own:n4-ku-ni-suru-heya', 's:tatoeba:194079', 's:tatoeba:202004', 's:own:n4-ku-ni-suru-oto'], ref: ['～く/ ～にする'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/adjective-suru-genki-ii-chapter-21/'], verified: true },
  { id: 'g:amari-nai', kind: 'grammar', level: 'N4', pattern: 'あまり/ぜんぜん 〜ない/〜ません/〜なかった', meaning: 'not very / not much; not at all', formation: 'あまり + negative: あまり[高|たか]くない, あまり[食|た]べません; ぜんぜん + negative: ぜんぜんわからない', notes: 'あまり softens a negative: "not very, not much, not often". ぜんぜん makes it total: "not at all". Both need a negative ending later in the sentence. In casual speech あんまり is common. [全然|ぜんぜん] has kanji above N4, so it is written ぜんぜん here.', examples: ['s:own:n4-amari-mise', 's:own:n4-zenzen-hon', 's:tatoeba:12957013', 's:tatoeba:230324', 's:tatoeba:9695689'], offList: 'not on Tanos N4; Bunpro lists あまり～ない at N4, japanesetest4you あまり～ない and 全然～ない at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%82%E3%81%BE%E3%82%8A-%E3%81%AA%E3%81%84', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%82%E3%81%BE%E3%82%8A%EF%BD%9E%E3%81%AA%E3%81%84-amarinai/', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%9C%E3%82%93%E3%81%9C%E3%82%93-zenzen/'], verified: true },
  { id: 'g:sonna-ni', kind: 'grammar', level: 'N4', pattern: 'そんなに/こんなに/あんなに', meaning: 'so (much), that (much), to such a degree', formation: 'そんなに / こんなに / あんなに + adjective or verb: そんなに[高|たか]い, こんなにたくさん; そんなに + negative: not that ~', notes: 'The こ・そ・あ set for degree: こんなに "this much" (here, with me), そんなに "that much" (what you said or have), あんなに "that much" (over there, or in the past we both know). With a negative, そんなに means "not that ~": そんなにむずかしくない "it\'s not that hard". In questions it often sounds surprised: どうしてそんなに[高|たか]いの？', examples: ['s:own:n4-sonna-ni-tesuto', 's:tatoeba:12312123', 's:tatoeba:4855', 's:tatoeba:11741527'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list そんなに at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%9D%E3%82%93%E3%81%AA%E3%81%AB', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%9D%E3%82%93%E3%81%AA%E3%81%AB-sonna-ni/'], verified: true },
  { id: 'g:passive', kind: 'grammar', level: 'N4', conjForm: 'passive', hl: ['([かがさたなばまらわ]れ|られ)(?=る|た|て|ま|な)'], pattern: 'V-れる/V-られる (passive)', meaning: 'be ~ed (by someone); have something done to you', formation: 'う-verbs: last sound to the あ-row + れる ([読|よ]まれる, [言|い]われる, [聞|き]かれる); る-verbs: る → られる ([食|た]べられる, [見|み]られる); する → される, [来|く]る → [来|こ]られる', notes: 'The person something is done to becomes the subject, and the doer takes に: [先生|せんせい]に[聞|き]かれた "I was asked by the teacher". Japanese also uses it for things that happen to you and annoy you, the "suffering passive": [電車|でんしゃ]の[中|なか]で[足|あし]をふまれた "someone stepped on my foot". For る-verbs the passive looks like the potential (g:potential, [食|た]べられる); に + doer or the situation tells you it is passive. All passives conjugate as る-verbs.', examples: ['s:own:n4-passive-ashi', 's:own:n4-passive-nikki', 's:tatoeba:13569023', 's:tatoeba:12018756'], ref: ['～られる'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/passive-sentences-genki-ii-chapter-21/', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%82%89%E3%82%8C%E3%82%8B-rareru-2/'], verified: true },
  { id: 'g:causative', kind: 'grammar', level: 'N4', conjForm: 'causative', hl: ['([かがさたなばまらわ]せ|させ)(?=る|た|て|ま|な)'], pattern: 'V-せる/V-させる (causative)', meaning: 'make someone ~; let someone ~', formation: 'う-verbs: last sound to the あ-row + せる ([行|い]かせる, [読|よ]ませる, [待|ま]たせる); る-verbs: る → させる ([食|た]べさせる); する → させる, [来|く]る → [来|こ]させる', notes: 'The causer is the subject; the person made (or allowed) to act takes に (or を with verbs like [行|い]く): [母|はは]は[弟|おとうと]にそうじをさせた "Mom made my brother clean". Whether it means "make" or "let" comes from context. 〜させてください asks permission for yourself: [休|やす]ませてください "please let me rest". Causatives conjugate as る-verbs.', examples: ['s:own:n4-causative-souji', 's:own:n4-causative-yomu', 's:tatoeba:138033', 's:tatoeba:146817', 's:tatoeba:8726978', 's:tatoeba:2105551'], ref: ['～させる'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/causative-sentences-genki-ii-chapter-22/', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%95%E3%81%9B%E3%82%8B-saseru/'], verified: true },
  { id: 'g:causative-passive', kind: 'grammar', level: 'N4', conjForm: 'causative-passive', hl: ['(させられ|[かがたなばまわら]され)(?=る|た|て|ま)'], pattern: 'V-させられる/V-される (causative-passive)', meaning: 'be made to ~ (against your will)', formation: 'Causative + passive: る-verbs させられる ([食|た]べさせられる); う-verbs あ-row + せられる, usually shortened to あ-row + される ([待|ま]たせられる → [待|ま]たされる, [飲|の]まされる); する → させられる, [来|く]る → [来|こ]させられる. す-verbs keep the long form ([話|はな]させられる)', notes: 'The person who had to do it is the subject and the one who made them takes に: [母|はは]にピアノをれんしゅうさせられた "my mother made me practise the piano". It always carries a feeling of "I didn\'t want to". Compare the causative (g:causative), where the one giving the order is the subject.', examples: ['s:own:n4-causative-passive-piano', 's:own:n4-causative-passive-shachou', 's:tatoeba:155026', 's:tatoeba:11846442', 's:tatoeba:225374'], ref: ['～させられる'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/causative-passive-sentences-genki-ii-chapter-23/', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%95%E3%81%9B%E3%82%89%E3%82%8C%E3%82%8B-saserareru/'], verified: true },
  { id: 'g:shika-nai', kind: 'grammar', level: 'N4', pattern: 'しか〜ない/〜ません/〜なかった', meaning: 'only ~, nothing but ~ (with a negative verb)', formation: 'N (+ particle) + しか + negative verb: [百|ひゃく][円|えん]しかありません, [日本|にほん]でしか[買|か]えない', notes: 'しか always pairs with a negative ending, but the meaning is positive "only": [百|ひゃく][円|えん]しかない "I have only 100 yen". It stresses that the amount is less than hoped. だけ (g:dake, N5) also means "only" but is neutral and takes a positive verb: [百|ひゃく][円|えん]だけある. しか replaces が and を; other particles stay in front of it (ここでしか).', examples: ['s:own:n4-shika-saifu', 's:tatoeba:11102012', 's:tatoeba:12882301', 's:tatoeba:155443', 's:tatoeba:9748980'], ref: ['しか～ない'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/number-mo-number-shika-negative-genki-ii-chapter-14/', 'https://japanesetest4you.com/flashcard/learn-japanese-grammar-39/'], verified: true },
  { id: 'g:number-mo', kind: 'grammar', level: 'N4', hl: ['(?<=[一二三四五六七八九十百千万億][^。、！？…「」もではがを]{0,3}|何[一-龥])(も)'], pattern: '〜も (number + も)', meaning: 'as many as ~, as much as ~ (more than expected)', formation: 'Number + counter + も: [三|さん][人|にん]も, [十|じゅう][時間|じかん]も, [二日|ふつか]も', notes: 'も after an amount says it is surprisingly large: [姉|あね]が[三|さん][人|にん]もいる "I have as many as three older sisters". With [何|なん] + counter it means "many": [何|なん][度|ど]も "many times", [何|なん][時|じ][間|あいだ]も "for hours". With [一|いち] + counter and a negative it means "not even one": [一度|いちど]も[行|い]ったことがない. しか (g:shika-nai) is the opposite: smaller than expected.', examples: ['s:own:n4-number-mo-neru', 's:own:n4-number-mo-party', 's:own:n4-number-mo-eki', 's:own:n4-number-mo-hon', 's:tatoeba:2113607'], ref: ['Number+も'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/number-mo-number-shika-negative-genki-ii-chapter-14/'], verified: true },
  { id: 'g:to-iwarete-iru', kind: 'grammar', level: 'N4', hl: ['(と(?:言|い)われて)'], pattern: '〜と言われている/〜といわれている', meaning: 'it is said that ~; people say ~', formation: 'Plain form + と[言|い]われている / と[言|い]われています (passive of [言|い]う + ている)', notes: 'Reports what people in general say or believe, without naming who: [朝|あさ]ごはんを[食|た]べるのは[体|からだ]にいいと[言|い]われています. It is common in explanations and reading passages. It is built from と[言|い]う (quotation), the passive (g:passive) and ている. For something one person told you, use 〜と[言|い]われた or 〜そうです (g:sou-da-hearsay).', examples: ['s:own:n4-to-iwarete-asagohan', 's:own:n4-to-iwarete-tatemono', 's:own:n4-to-iwarete-raamen'], offList: 'not on Tanos N4; Bunpro lists といわれている at N4, japanesetest4you has a と言われている page in its N4 series', sources: ['https://bunpro.jp/grammar_points/%E3%81%A8%E3%81%84%E3%82%8F%E3%82%8C%E3%81%A6%E3%81%84%E3%82%8B', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%A8%E3%81%84%E3%82%8F%E3%82%8C%E3%81%A6%E3%81%84%E3%82%8B-to-iwarete-iru/'], verified: true },
  { id: 'g:sonkeigo-verbs', kind: 'grammar', level: 'N4', keigo: 'up', pairs: [['いる', 'いらっしゃる', 'おいでになる'], ['行く', 'いらっしゃる', 'おいでになる'], ['来る', 'いらっしゃる', 'おいでになる'], ['する', 'なさる'], ['言う', 'おっしゃる'], ['食べる', 'めしあがる', '召し上がる'], ['飲む', 'めしあがる', '召し上がる'], ['見る', 'ごらんになる', 'ご覧になる']], hl: ['(いらっしゃ|なさ|おっしゃ|めしあが)(?=[いっらりるれ])'], pattern: 'いらっしゃる/なさる/おっしゃる/めしあがる (honorific verbs)', meaning: 'special respectful verbs for what someone above you does', formation: 'いる / [行|い]く / [来|く]る → いらっしゃる; する → なさる; [言|い]う → おっしゃる; [食|た]べる / [飲|の]む → めしあがる; [見|み]る → ごらんになる. ます-form: いらっしゃいます, なさいます, おっしゃいます (る → い + ます)', notes: 'Respectful language ([尊敬語|そんけいご]) raises the other person by using a special verb for their action; never use it for yourself. These are the most common ones. Their ます-form is irregular: the る becomes い (いらっしゃいます, not いらっしゃります). Verbs without a special form use お〜になる (g:o-ni-naru).', examples: ['s:own:n4-sonkeigo-kyoushitsu', 's:own:n4-sonkeigo-meshiagaru', 's:tatoeba:4805143', 's:tatoeba:226566', 's:tatoeba:202257', 's:tatoeba:228622'], offList: 'not on Tanos N4; Bunpro lists いらっしゃる and なさる at N4, japanesetest4you いらっしゃる / なさる at N4, Genki II ch.19 teaches the honorific verbs (おっしゃる and めしあがる come from that lesson)', sources: ['https://bunpro.jp/grammar_points/%E3%81%84%E3%82%89%E3%81%A3%E3%81%97%E3%82%83%E3%82%8B', 'https://bunpro.jp/grammar_points/%E3%81%AA%E3%81%95%E3%82%8B', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%84%E3%82%89%E3%81%A3%E3%81%97%E3%82%83%E3%82%8B-irassharu/', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/honorific-verbs-keigo-genki-ii-chapter-19/'], verified: true },
  { id: 'g:o-ni-naru', kind: 'grammar', level: 'N4', keigo: 'up', pairs: [['待つ', 'おまちになる', 'お待ちになる'], ['書く', 'おかきになる', 'お書きになる'], ['帰る', 'おかえりになる', 'お帰りになる'], ['使う', 'おつかいになる', 'お使いになる'], ['読む', 'およみになる', 'お読みになる'], ['持つ', 'おもちになる', 'お持ちになる']], hl: ['(お)(?=[一-龯]+[きしちにびみりいぎえけべめれせ]?にな)'], pattern: 'お V-stem になる', meaning: 'respectful form of any verb (someone above you does ~)', formation: 'お + V-ます stem + になる: お[帰|かえ]りになる, お[待|ま]ちになる, お[読|よ]みになる; ご + する-noun + になる (ご[説明|せつめい]になる)', notes: 'The general recipe for respectful speech when a verb has no special form (g:sonkeigo-verbs): [先生|せんせい]はもうお[帰|かえ]りになりました "the teacher has already gone home". It conjugates like なる: お[読|よ]みになりましたか. It does not work for one-syllable stems ([見|み]る, [寝|ね]る), which use their own forms (ごらんになる). Like all [尊敬語|そんけいご], never use it about yourself.', examples: ['s:own:n4-o-ni-naru-kaeri', 's:tatoeba:4913', 's:tatoeba:198421', 's:tatoeba:3357887', 's:tatoeba:9546334'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list お～になる at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%8A-%E3%81%AB%E3%81%AA%E3%82%8B', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%8A%EF%BD%9E%E3%81%AB%E3%81%AA%E3%82%8B-oni-naru/'], verified: true },
  { id: 'g:o-kudasai', kind: 'grammar', level: 'N4', hl: ['(お)(?=[一-龯]+[きしちにびみりいぎえけべめれせ]?ください)'], pattern: 'お V-stem ください', meaning: 'please ~ (very polite request)', formation: 'お + V-ます stem + ください: お[待|ま]ちください, お[入|はい]りください, お[書|か]きください; ご + する-noun + ください (ご[注意|ちゅうい]ください); お + noun: お[電話|でんわ]ください', notes: 'A step more polite than 〜てください (N5), heard from shop staff, receptionists and announcements: [少|すこ]しお[待|ま]ちください "please wait a moment". It asks the listener to do something, so it is respectful language aimed at them. The same verbs that cannot take お〜になる ([見|み]る, [寝|ね]る) cannot take this either; use ごらんください for "please look".', examples: ['s:own:n4-o-kudasai-suwari', 's:own:n4-o-kudasai-kochira', 's:tatoeba:10282137', 's:tatoeba:223201', 's:tatoeba:228854'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list お～ください at N4; Genki II ch.19 teaches it as respectful advice', sources: ['https://bunpro.jp/grammar_points/%E3%81%8A-%E3%81%8F%E3%81%A0%E3%81%95%E3%81%84', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%8A%EF%BD%9E%E3%81%8F%E3%81%A0%E3%81%95%E3%81%84-okudasai/', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/giving-respectful-advice-genki-ii-chapter-19/'], verified: true },
  { id: 'g:o-suru', kind: 'grammar', level: 'N4', keigo: 'down', pairs: [['持つ', 'おもちする', 'お持ちする'], ['送る', 'おおくりする', 'お送りする'], ['待つ', 'おまちする', 'お待ちする'], ['返す', 'おかえしする', 'お返しする'], ['手伝う', 'おてつだいする', 'お手伝いする'], ['知らせる', 'おしらせする', 'お知らせする']], hl: ['(お)(?=[一-龯]+[きしちにびみりいぎえけべめれせ]?(?:し|いたし))'], pattern: 'お V-stem する/します', meaning: 'humble form: I (humbly) do ~ for you', formation: 'お + V-ます stem + する: お[持|も]ちする, お[送|おく]りする, お[返|かえ]しする; ご / お + する-noun + する (ご[案内|あんない]する, お[電話|でんわ]する); even humbler with いたす: お[持|も]ちいたします', notes: 'Humble language ([謙譲語|けんじょうご]) lowers yourself when your action affects the other person: かばんをお[持|も]ちしましょうか "shall I carry your bag?". It is for your own actions only; for the other person\'s actions use お〜になる (g:o-ni-naru). The verb must involve the other person, so お[歩|ある]きする "I humbly walk" makes no sense.', examples: ['s:own:n4-o-suru-kaesu', 's:tatoeba:226244', 's:tatoeba:10612520', 's:tatoeba:174354', 's:tatoeba:10838340'], offList: 'not on Tanos N4; Bunpro lists お〜する at N4; Genki II ch.20 teaches it as a humble expression', sources: ['https://bunpro.jp/grammar_points/%E3%81%8A-%E3%81%99%E3%82%8B', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/humble-expressions-genki-ii-chapter-20/'], verified: true },
  { id: 'g:itasu', kind: 'grammar', level: 'N4', keigo: 'down', pairs: [['する', 'いたす', 'いたします', '致す', '致します'], ['行く', 'まいる', 'まいります', '参る', '参ります'], ['来る', 'まいる', 'まいります', '参る', '参ります'], ['言う', 'もうす', 'もうします', '申す', '申します', 'もうしあげる', '申し上げる']], hl: ['(いたし|まいり|もうし)(?=ま)'], pattern: 'いたします/まいります/もうします (humble verbs)', meaning: 'special humble verbs for your own actions', formation: 'する → いたす (いたします); [行|い]く / [来|く]る → まいる (まいります); [言|い]う → もうす (もうします); also もらう → いただく, [見|み]る → はいけんする', notes: 'Humble verbs ([謙譲語|けんじょうご]) replace an ordinary verb when you talk about what you or your side does, to someone you respect: お[電話|でんわ]いたします "I will call you", すぐまいります "I\'ll come right away", [田中|たなか]ともうします "my name is Tanaka". They are almost always used in the ます-form. Compare the honorific verbs (g:sonkeigo-verbs), which are for the other person.', examples: ['s:own:n4-itasu-moushimasu', 's:tatoeba:10982402', 's:tatoeba:174355', 's:tatoeba:214978', 's:tatoeba:80604'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list いたす at N4; Genki II ch.20 teaches まいる / もうす / いたす as extra-modest expressions', sources: ['https://bunpro.jp/grammar_points/%E3%81%84%E3%81%9F%E3%81%99', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%84%E3%81%9F%E3%81%99-itasu/', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/extra-modest-expressions-genki-ii-chapter-20/'], verified: true },
  { id: 'g:gozaimasu', kind: 'grammar', level: 'N4', hl: ['(ござい)(?=ま)'], pattern: 'ございます/でございます', meaning: 'there is / is (very polite)', formation: 'N + が + ございます (= あります); N + でございます (= です); negative ございません', notes: 'The very polite stand-ins for ある and です, heard in shops, hotels and announcements: トイレは[二|に][階|かい]にございます "the toilets are on the second floor", こちらでございます "here it is". The speaker uses them to be polite to the listener, about things, not people (for people use いらっしゃる). おはようございます and ありがとうございます are set phrases built on the same word.', examples: ['s:own:n4-gozaimasu-toire', 's:own:n4-gozaimasu-erebeetaa', 's:tatoeba:214063', 's:tatoeba:229205', 's:tatoeba:1336459'], offList: 'not on Tanos N4; Bunpro lists ございます and でございます at N4, japanesetest4you both at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%94%E3%81%96%E3%81%84%E3%81%BE%E3%81%99', 'https://bunpro.jp/grammar_points/%E3%81%A7%E3%81%94%E3%81%96%E3%81%84%E3%81%BE%E3%81%99', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%94%E3%81%96%E3%81%84%E3%81%BE%E3%81%99-gozaimasu/', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%A7%E3%81%94%E3%81%96%E3%81%84%E3%81%BE%E3%81%99-de-gozaimasu/'], verified: true },
  { id: 'g:ja-nai-ka', kind: 'grammar', level: 'N4', pattern: 'じゃないか/ではないか/じゃないですか/じゃん', meaning: 'isn\'t it ~! (I told you / look); come on, let\'s ~', formation: 'Plain form / N / な-adj + じゃないか (casual), ではないか (written), じゃないですか (polite); very casual じゃん; volitional + じゃないか = "let\'s"', notes: 'Not a real question: the speaker points out something the listener should already know or see, often with surprise or mild blame: いつも[言|い]ってるじゃないか "I\'m always telling you!". It is said with falling intonation. A rising じゃない？ asks for agreement ("isn\'t it?"), and 〜んじゃないかな is a soft guess. After the volitional it urges: [飲|の]もうじゃないか "come on, let\'s drink".', examples: ['s:own:n4-ja-nai-ka-itta', 's:own:n4-ja-nai-ka-kanji', 's:tatoeba:4717937', 's:tatoeba:9112549', 's:tatoeba:3507456'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list じゃないか at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%98%E3%82%83%E3%81%AA%E3%81%84%E3%81%8B', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%98%E3%82%83%E3%81%AA%E3%81%84%E3%81%8B-janai-ka/'], verified: true },
  { id: 'g:kana-kashira', kind: 'grammar', level: 'N4', pattern: 'かな/かしら', meaning: 'I wonder (if / whether) ~', formation: 'Plain form + かな / かしら (N / な-adj directly: [元気|げんき]かな); のかな / のかしら to wonder about a reason', notes: 'Ends a sentence when you are wondering aloud, half to yourself: あした、[雨|あめ]がふるかな "I wonder if it\'ll rain tomorrow". かな is used by everyone; かしら is softer and mostly used by women, a little old-fashioned. 〜ないかな can be a hopeful wish ([早|はや]く[春|はる]にならないかな) or a soft request ([待|ま]ってくれないかな). In polite speech use 〜でしょうか.', examples: ['s:own:n4-kana-ame', 's:tatoeba:9854115', 's:tatoeba:10528638', 's:tatoeba:11162294', 's:tatoeba:229506'], offList: 'not on Tanos N4; Bunpro lists かな and かしら at N4, japanesetest4you both at N4', sources: ['https://bunpro.jp/grammar_points/%E3%81%8B%E3%81%AA', 'https://bunpro.jp/grammar_points/%E3%81%8B%E3%81%97%E3%82%89', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%8B%E3%81%AA-kana/', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%8B%E3%81%97%E3%82%89-kashira/'], verified: true },
  { id: 'g:ka-dou-ka', kind: 'grammar', level: 'N4', pattern: '〜かどうか', meaning: 'whether or not ~ (a yes/no question inside a sentence)', formation: 'Plain form + かどうか ([来|く]るかどうか, [行|い]けるかどうか); N / な-adj directly + かどうか (OKかどうか); then [分|わ]からない, [知|し]らない, [聞|き]く, etc.', notes: 'Turns a yes/no question into part of a bigger sentence: [雨|あめ]がふるかどうか、わかりません "I don\'t know whether it will rain". The verb after it is usually one of knowing, asking or checking. When the question has a question word, drop どうか and keep only か: [何|なん][時|じ]に[来|く]るか[知|し]らない. The verb before it is in plain form even in polite speech.', examples: ['s:own:n4-ka-dou-ka-ame', 's:own:n4-ka-dou-ka-sensei', 's:tatoeba:215673', 's:tatoeba:10187698', 's:tatoeba:171171', 's:tatoeba:9964050'], ref: ['～かどうか'], sources: ['tanos', 'https://wp.stolaf.edu/japanese/grammar-index/genki-i-ii-grammar-index/questions-within-larger-sentences-genki-ii-chapter-20/', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%8B%E3%81%A9%E3%81%86%E3%81%8B-ka-dou-ka/'], verified: true },
  { id: 'g:kai', kind: 'grammar', level: 'N4', pattern: 'かい', meaning: 'casual yes/no question ending (friendly, mostly male speech)', formation: 'Plain form + かい: [行|い]くかい？, [元気|げんき]かい？; のかい to ask about a reason or situation', notes: 'A casual question ending, warmer than a bare rising tone and heard mostly from men and older speakers, or from adults to children: そう[思|おも]うかい？ "you think so?". It is only for yes/no questions; with a question word ([何|なん], どこ) the casual form is だい. You mostly need to recognise it; in your own speech a rising の？ or plain form is enough.', examples: ['s:own:n4-kai-kaeru', 's:tatoeba:213775', 's:tatoeba:194166', 's:tatoeba:4970'], offList: 'not on Tanos N4; Bunpro + japanesetest4you list かい at N4 (low priority: recognition only)', sources: ['https://bunpro.jp/grammar_points/%E3%81%8B%E3%81%84', 'https://japanesetest4you.com/flashcard/learn-jlpt-n4-grammar-%E3%81%8B%E3%81%84-kai/'], verified: true }
]);
